BEGIN;

SET LOCAL search_path = public;

ALTER TABLE public.professor_review ENABLE ROW LEVEL SECURITY;

ALTER TABLE public.professor_review_course ENABLE ROW LEVEL SECURITY;

WITH review_input (
  professor_id, comment, ease_score, quality_score, clarity_score, fairness_score,
  attendance_required, grade_received, engagement_level, tags, created_at, import_key, course_ids
) AS (
  VALUES 
    (311::BIGINT, 'Es buen profesor, cumple con el cronograma y explica bien, lo que pasa es que tiene que dedicarle demasiado tiempo al curso, no es complicado, pero trate de hacer y participar en todo lo que pueda.'::TEXT, 4.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, '90'::TEXT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Requiere mucha lectura', 'Da crédito extra']::TEXT[], '2025-12-16T00:00:00+00:00'::TIMESTAMPTZ, 'd69a6ef2a84e25fea84d48b7d18538ce3c154d94bf646be79d3e62817dea5610'::TEXT, ARRAY[1045]::BIGINT[]),
    (311::BIGINT, 'Como profesor es bueno, explica bien y se nota que sabe mucho. Va a tener que dedicarle una cantidad exagerada de horas a las tareas pero no son imposibles, lo peor son los exámenes que son LARGUÍSIMOS y mete TODA la materia, el mae ayuda bastante al final del curso pero es duro'::TEXT, 2.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, '75'::TEXT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Deja trabajos largos', 'Exámenes retadores']::TEXT[], '2025-12-11T00:00:00+00:00'::TIMESTAMPTZ, 'aabca69f58f9627f7a03e46e21eb7359427b11d2d284b45ad31a711424662c55'::TEXT, ARRAY[1017]::BIGINT[]),
    (311::BIGINT, 'Todos los comentarios son veridicos. Pero, si tuvo que matricular con el, haga TODOS los pts extra que pueda, no acumule tareas ni resumenes y si no logra terminar una tarea, mandela asi, los asistentes califican decente. Lleve buena comida a los examenes. Duro, pero, si llega al final, puede pasar.'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, '90'::TEXT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Muchas tareas', 'Exámenes retadores']::TEXT[], '2025-12-05T00:00:00+00:00'::TIMESTAMPTZ, 'efe4e8e065f9c14e53e1130ae65006dc48feded364789407ccc0c85d99b219f8'::TEXT, ARRAY[1017]::BIGINT[]),
    (311::BIGINT, 'Califica muy duro, la cantidad de horas que le tienes que dedicar a la semana son exageradas. Como recomendación hagan todos los puntos extras, no falten a clases, hagan todas las tareas y resúmenes. Los exámenes son duros, largos y en domingos. Es pasable pero requiere muchísimo tiempo.'::TEXT, 4.0::NUMERIC(3,1), 4.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, '80'::TEXT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Muchas tareas', 'Exámenes retadores']::TEXT[], '2025-12-04T00:00:00+00:00'::TIMESTAMPTZ, 'f2e3294a01d88eeaa72ccfaf82b1fff2bd3c678b6c885df6f010d3a6cf66a78a'::TEXT, ARRAY[1017]::BIGINT[]),
    (311::BIGINT, 'En lo personal siento que el problema con este profesor no es que su curso sea difícil (que lo es) sino que deja una cantidad de trabajo tan abrumadora que a uno ni le da tiempo de aprender bien. Si no te gusta leer ni te acerques.'::TEXT, 2.0::NUMERIC(3,1), 5.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, '75'::TEXT, NULL::SMALLINT, ARRAY['Requiere mucha lectura', 'Deja trabajos largos', 'Exámenes retadores']::TEXT[], '2025-07-21T00:00:00+00:00'::TIMESTAMPTZ, 'd4685c2c538f82789984697f03b660b7c1e34417c57a471b26440173810d20e0'::TEXT, ARRAY[1017]::BIGINT[]),
    (311::BIGINT, 'El curso se pasa solo, si hace todos los resúmenes y trabajos, no deje que se le acumulen, el mae califica duro, y los exámenes son estúpidamente largos (5-8 horas y son los Domingos) Haga todos los puntos extra que pueda, no falte a clases. Es cansado, si se quiere, busque otra opcion'::TEXT, 4.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, '70'::TEXT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Muchas tareas', 'Requiere mucha lectura']::TEXT[], '2025-06-29T00:00:00+00:00'::TIMESTAMPTZ, 'cae320cb1ec62c037b1cbb1531d14267de14fca09d4d819af7f599a8a59e1939'::TEXT, ARRAY[1017]::BIGINT[]),
    (311::BIGINT, 'Ninguno'::TEXT, 6.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULL::TEXT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Requiere mucha lectura', 'Asistencia obligatoria']::TEXT[], '2025-06-22T00:00:00+00:00'::TIMESTAMPTZ, 'a76a31f49345929a85eceb50ccafe418a290d35f68e39db270f04a7b2c26d860'::TEXT, ARRAY[1017]::BIGINT[]),
    (311::BIGINT, 'Como dicen las demas calificaciones en efecto, es un profesor que no es para cualquiera. En lo personal, me parece un profesor increible, se aprende a la fuerza por las tareas, PERO SE APRENDE, que eso a mi me parece lo mas importante. Aun ni siquiera se si pase pero 0 bronca con el profe, lo tqm.'::TEXT, 4.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULL::TEXT, NULL::SMALLINT, ARRAY['Muy cómico', 'Muchas tareas', 'Requiere mucha lectura']::TEXT[], '2025-06-04T00:00:00+00:00'::TIMESTAMPTZ, '7a47b870e03d1063f83ad1da604f16d13927e95b9647c8d8b6c6cbdb73a87036'::TEXT, ARRAY[1017]::BIGINT[]),
    (311::BIGINT, 'Una leyenda viviente Don Kirstein, super infravalorado por la cantidad de bretes que manda, pero si ustedes se ordenan pasan sobrados. Entre él y Jorge para lenguajes lo elegí a Kirstein porque la verdad se aprende DEMASIADO, con Jorge NADA , como dice el dicho: “Los de Kirstein son unas máquinas”'::TEXT, 4.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULL::TEXT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Respetado por los estudiantes', 'Clases excelentes']::TEXT[], '2025-05-18T00:00:00+00:00'::TIMESTAMPTZ, '7ef66ba0b8d0066e1f00656237a29a3b5e0c6d0aee006e27061f80ade5a452c8'::TEXT, ARRAY[1045]::BIGINT[]),
    (311::BIGINT, 'Es un profe no para cualquiera . Por semestre deja 130–140 lecturas , de estas 4 o 5 resúmenes semanales y 1 tarea de 15 o 35 horas bisemanal . Exámenes de 5 horas, extendible a 9 horas los domingos. Sus tareas, salvo lecturas, son únicas y no están en Google. Aprenderá mucho si soporta la carga.'::TEXT, 2.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, '70'::TEXT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Deja trabajos largos', 'Exámenes retadores']::TEXT[], '2025-05-12T00:00:00+00:00'::TIMESTAMPTZ, 'c8e412f0b9efb43f9a66c822a196a2e2a0a4da0468194ef6f0991b2d38211783'::TEXT, ARRAY[1017]::BIGINT[]),
    (311::BIGINT, 'Muy Facil'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, '100'::TEXT, NULL::SMALLINT, ARRAY['Muy cómico', 'La participación importa', 'Da crédito extra']::TEXT[], '2025-02-14T00:00:00+00:00'::TIMESTAMPTZ, 'f8d4428e921a087b7be0322daa45accbb03c738128cd31737033495d366bc01d'::TEXT, ARRAY[1017]::BIGINT[]),
    (311::BIGINT, 'El curso es bastante laborioso, muchos trabajos. Depende del asistente puede que le vaya muy bien en las notas. Muchas lecturas y son varias tareas programadas de diferentes lenguajes.'::TEXT, 6.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULL::TEXT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Requiere mucha lectura', 'Clases largas']::TEXT[], '2024-10-24T00:00:00+00:00'::TIMESTAMPTZ, '5198f0494eb86a134b429ddc5bfd78bf37d6470decdd9ae4d80bf534982157de'::TEXT, ARRAY[1045]::BIGINT[]),
    (311::BIGINT, 'Si perder el tiempo tuviera un nombre se llamaría KIrstein Gatjens. Mae yo le pasé compi, pero NO APRENDÍ NADA. Como en todos los cursos que le he pasado. El como persona es excelente y sabe muchísimo, si fuera buen profe todos quisieran llevar con el porque el mae sabe mucho. HAGA TODOS LOS EXTRAS'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, '90'::TEXT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Asistencia obligatoria', 'Clases largas']::TEXT[], '2024-06-28T00:00:00+00:00'::TIMESTAMPTZ, 'ff2a5fc5e8331398b2ceb3202a84bef0fd5596c77171d0e9542e32076a2400dc'::TEXT, ARRAY[1054]::BIGINT[]),
    (311::BIGINT, 'El profe se pierde demasiado en clase porque no las lleva listas y se poner a hacer todo ahí mismo, los exámenes son demasiado largos y el proyecto es largo pero no imposible. Haga todos los puntos extra e invente todo lo posible para que le suba la nota. Piensa que uno solo lleva el curso de el'::TEXT, 4.0::NUMERIC(3,1), 3.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, '70'::TEXT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Asistencia obligatoria', 'Deja trabajos largos']::TEXT[], '2024-06-12T00:00:00+00:00'::TIMESTAMPTZ, '197b21ce69a939ef449f070a35c260ad363eedc1fccee20abebc869aea3c2d4b'::TEXT, ARRAY[1054]::BIGINT[]),
    (311::BIGINT, 'La clave para pasar con K es simple y consiste en 3 pasos: 1) Entregue TODO, así usted vea que no vale la pena, entregue todas las tareas y resumenes. 2) Llegue hasta el final, no abandone el curso por más feo que la vea, siempre vaya a todas las clases. 3) Haga los puntos extra, todos los que pueda'::TEXT, 2.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, '85'::TEXT, NULL::SMALLINT, ARRAY['Muy cómico', 'Muchas tareas', 'Da crédito extra']::TEXT[], '2024-06-12T00:00:00+00:00'::TIMESTAMPTZ, '9249aaa85a8526781443edcf13e96ae0856914b61b5da8aae6892687d455a1bb'::TEXT, ARRAY[1045]::BIGINT[]),
    (311::BIGINT, 'Si quiere pasar debe hacer todos los extras, el proyecto es difícil pero no imposible, da mucho tiempo para hacerlo y es muy flexible con las fechas, aproveche cada día que tiene para hacerlo y le va a ir bien, la documentación es muy importante. No descuide las lecturas, estudie bien para el examen'::TEXT, 4.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, '85'::TEXT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Requiere mucha lectura', 'Exámenes retadores']::TEXT[], '2024-06-10T00:00:00+00:00'::TIMESTAMPTZ, 'abb67cdbd3ceb2c54fd68774746c21981031daaecbfd87ab03b0c387d6ae40e9'::TEXT, ARRAY[1054]::BIGINT[]),
    (311::BIGINT, 'La clase es tranquila, pero debe mentalizarse a que un curso con él será la carga de 3 cursos (hay lecturas, extras, proyecto y exámenes). Para pasar tranquilo, haga todo, especialmente los extras. Como persona y su conocimiento es excelente, es comprensivo, pero es demasiado brete.'::TEXT, 2.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, '75'::TEXT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Requiere mucha lectura', 'Da crédito extra']::TEXT[], '2024-06-07T00:00:00+00:00'::TIMESTAMPTZ, '40399b246705c4454c93596efcfcdfcc5f08bed2e631460d8e2f926955467075'::TEXT, ARRAY[1054]::BIGINT[]),
    (311::BIGINT, 'Trata muy mal a los estudiantes, es extremadamente irrespetuoso. La agarra en contra de una persona, le dice a toda la clase estupidos porque los compara con el mejor estudiante para el. No es un ambiente para nada bonito y como deja una cantidad exagerada de cosas no se aprende bien'::TEXT, 2.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, '75'::TEXT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Asistencia obligatoria', 'Exámenes retadores']::TEXT[], '2023-11-27T00:00:00+00:00'::TIMESTAMPTZ, '1faf16e9ddc68401ef4e9be5996c5f40bcf5ca15ae2da9852c8e33e66b27eb05'::TEXT, ARRAY[1045]::BIGINT[]),
    (311::BIGINT, 'Deja muchas tareas, y son tan largas que son imposibles de terminar. No se sienta mal si no las puede entregar completas, igualmente entréguelas, ya que las revisa el asistente que no es duro calificando. Exámenes los Domingos y con una duración de unas 5 horas cada uno. Con un 60 se puede pasar.'::TEXT, 2.0::NUMERIC(3,1), 5.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, '80'::TEXT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Da crédito extra', 'Deja trabajos largos']::TEXT[], '2023-11-20T00:00:00+00:00'::TIMESTAMPTZ, '6a259edcfa39af74a5d642e60456e52e2660381c8bedc89ac0083bf3f38d303e'::TEXT, ARRAY[1017]::BIGINT[]),
    (311::BIGINT, 'Este mae piensa que solo recibimos este curso, deja proyectos a morir y el mae piensa que es el mejor profesional del TEC cuando es de los peores que hay.'::TEXT, 2.0::NUMERIC(3,1), 4.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULL::TEXT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Deja trabajos largos', 'Exámenes retadores']::TEXT[], '2023-11-19T00:00:00+00:00'::TIMESTAMPTZ, 'dad0c5052074940b2b977f41cf9e721b45949cf6293cc7f67218d2dd9dddc42a'::TEXT, ARRAY[1032]::BIGINT[]),
    (311::BIGINT, 'Kirstein que cree que es el mejor profesor del TEC. Trata mal a otros funcionarios que por a por b pasan a su clase a preguntar cosas que con uno no o un si se pueden responder'::TEXT, 6.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULL::TEXT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Requiere mucha lectura', 'Asistencia obligatoria']::TEXT[], '2023-10-05T00:00:00+00:00'::TIMESTAMPTZ, 'f2f7a63756cf97c7f01df0564107cc7f43baf5b6fe7e7958a13ede15472228ee'::TEXT, ARRAY[1032]::BIGINT[]),
    (311::BIGINT, 'No enseña nada, cree que a uno solo le interesan sus puntos extra entonces es lo unico por lo que se preocupa, no resuelve dudas y es prepotente cuando uno le habla, deja muchas tareas y trabajos que no serian problema si enseñara como hacer las cosas, usa herramientas y libros de hace 20+ años'::TEXT, 6.0::NUMERIC(3,1), 3.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULL::TEXT, NULL::SMALLINT, ARRAY['Muchas tareas']::TEXT[], '2023-08-24T00:00:00+00:00'::TIMESTAMPTZ, '006501f40cd811da407dc2b9e6c5484cf7f00275cbf553382cdcff60d60f5e40'::TEXT, ARRAY[1032]::BIGINT[]),
    (311::BIGINT, 'Es el peor profesor en la historia del TEC, no tiene ni idea de lo que es un ambiente laboral y lo hace seguir reglas estrictas de los años 1001'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, '70'::TEXT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Requiere mucha lectura', 'Deja trabajos largos']::TEXT[], '2023-06-24T00:00:00+00:00'::TIMESTAMPTZ, 'b8d0ccb640430165e0a756defc2a32e2c1411c1b95af80d6317a807ac66cef27'::TEXT, ARRAY[1054]::BIGINT[]),
    (311::BIGINT, 'Los exámenes no es tan importantes,presentando todos los aprox 60 resúmenes y todas las tareas extremadamente extensas para tener un valor de 1, 2 ó 3 puntos. Al final otorga muchos puntos extra(alrededor de 15 ó 20) por tareas extra, asistencia, haber presentado todas las tareas, participación, etc'::TEXT, 4.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, '70'::TEXT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Asistencia obligatoria', 'Da crédito extra']::TEXT[], '2023-06-24T00:00:00+00:00'::TIMESTAMPTZ, 'f4466d905127b3b07b4c7cc9832c57d35cba16c6ae7a10218262feda8d832a4c'::TEXT, ARRAY[1017]::BIGINT[]),
    (311::BIGINT, 'K deja demasiadas tareas, tienes que hacer tres examenes de 150 preguntas con un estimado por cada examen de 4.5 horas. Adaptarse a este ritmo no es fácil, pero sales mejor preparado (por estudiar tanto). Un tercio de la clase pasa, los demás deciden abandonar el primer mes.'::TEXT, 2.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, '70'::TEXT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Requiere mucha lectura', 'Asistencia obligatoria']::TEXT[], '2023-06-22T00:00:00+00:00'::TIMESTAMPTZ, 'a332e6bb90b74e18525d85e0e518b0b4cab9e01f920edb18b81007c61db9e31f'::TEXT, ARRAY[1017]::BIGINT[]),
    (311::BIGINT, 'Profesor mediocre, hace la asistencia obligatoria para llegar a medio explicar la materia, y la materia que da ni siquiera la ha terminado de redactar (incompleta). Hace el curso muy difícil para lo que es. Si lo va a llevar con él, asegúrese que es definitivamente la única opción que tenga.'::TEXT, 2.0::NUMERIC(3,1), 3.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, '85'::TEXT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Muchas tareas', 'Requiere mucha lectura']::TEXT[], '2023-06-09T00:00:00+00:00'::TIMESTAMPTZ, '6924d0cbeb4693800563a6919f7fd68b5dd5c8b5d87a477bc7e176b64f2af33a'::TEXT, ARRAY[1017]::BIGINT[]),
    (311::BIGINT, 'HUYA MAE NO COMA CUENTO, DE 22 ESTUDIANTES EN UN CURSO SOLO 5 PASARON!!!!'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULL::TEXT, NULL::SMALLINT, ARRAY['Muchos exámenes', 'Deja trabajos largos', 'Exámenes retadores']::TEXT[], '2023-01-19T00:00:00+00:00'::TIMESTAMPTZ, '093c16b5cac8c76a6291f53f2db665d5f1db3617418a80cb1f12b34a3f090489'::TEXT, ARRAY[1017]::BIGINT[]),
    (311::BIGINT, 'Sin importar co cual profe lleven este curso, no se entiende. En el caso de este profe, deja demasiados trabajos, pero también puntos extra. Gracias a los puntos extras fue que pasé el curso, así que si no tienen otra opción, hagan todos los puntos extras posibles. Btw, el examen final es una basura'::TEXT, 4.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, '80'::TEXT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Muchas tareas', 'La participación importa']::TEXT[], '2022-12-29T00:00:00+00:00'::TIMESTAMPTZ, '00eb8bbfd80f48e4fa9a59e91af02702c9c0f04779964a0774d0fb45e2bcdfdb'::TEXT, ARRAY[1032]::BIGINT[]),
    (311::BIGINT, 'No vuelvo a matricular con este señor, en mi vida. Aunque tenga que esperarme un semestre para cursar la materia. Él piensa que solo se lleva esa materia. Es demasiado trabajo y muy difícil. DEMASIADO. Porfavor, si valora su salud mental, no matricule con este señor. Se los ruego.'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, '75'::TEXT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Asistencia obligatoria', 'Deja trabajos largos']::TEXT[], '2022-12-04T00:00:00+00:00'::TIMESTAMPTZ, 'cad46b3e88af614184b86c455a48b256176cd3cd5702a160fa30cbf222313d60'::TEXT, ARRAY[1017]::BIGINT[]),
    (311::BIGINT, 'El profe es excelente, sin embargo no lo puedo recomendar. El profe piensa que el curso vale todos los 18 créditos de un bloque completo. Si le toca matricular con él prepárese y sepa que sí se puede pasar. Haga todos los trabajos, entregue algo aunque esté mal e intente conseguir todo lo extra.'::TEXT, 2.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, '70'::TEXT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Muchas tareas', 'Exámenes retadores']::TEXT[], '2022-07-12T00:00:00+00:00'::TIMESTAMPTZ, '9f202aa6dda938860d436604d7061a4d1f4e66ca09b98fca5143fc436e5b4ba3'::TEXT, ARRAY[1017]::BIGINT[]),
    (311::BIGINT, 'Si va a matricular con él prepárese para dedicarle mucho tiempo al curso, los exámenes son largos y complicados, deja muchas tareas pero también deja otras actividades por puntos extra. A pesar de eso no es una mala persona, simplemente le toca impartir una materia pesada. Vaya a las clases!!!'::TEXT, 4.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULL::TEXT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Requiere mucha lectura', 'Da crédito extra']::TEXT[], '2022-06-16T00:00:00+00:00'::TIMESTAMPTZ, '147281c2acbd3a6866ae0dad99a62cc19673c47e32e629d06c695d2d8350531d'::TEXT, ARRAY[1017]::BIGINT[]),
    (311::BIGINT, 'Simplemente huya, a no ser que sea su ultima opción no matricule con el bajo ningún motivo si quiere tener salud mental para el resto del semestre, yo ya quedé curado con este señor para el resto de la carrera'::TEXT, 2.0::NUMERIC(3,1), 3.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, '70'::TEXT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Da crédito extra', 'Deja trabajos largos']::TEXT[], '2022-06-08T00:00:00+00:00'::TIMESTAMPTZ, 'cf8ebb378cbb000ea22236da1ae5419c173eaf79c0f6024e63aab7ae21a3697c'::TEXT, ARRAY[1017]::BIGINT[]),
    (311::BIGINT, 'No sé cómo ponen a un incompetente a ser profesor, un mae con 0 experiencia en el mundo real, este mae con costos sabe usar Google y cree que vivimos en 1980 por ende todo lo que "enseña" es así, viejo y desactualizado.'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULL::TEXT, NULL::SMALLINT, ARRAY[]::TEXT[], '2022-05-27T00:00:00+00:00'::TIMESTAMPTZ, 'ad441109f8600359a7ef5aef1fd383e191662ab24d91a794a8e6503fe68a6392'::TEXT, ARRAY[1032]::BIGINT[]),
    (311::BIGINT, 'La gente que dice "se pasa solo haciendo los trabajos" pues claro, el problema es que en el semestre dejó 29 trabajos pesadísimos y solo habían 18 semanas. A eso sumele que uno lleva más materias. Al profesor se le olvida que su curso vale 4 créditos, no 20...'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, '70'::TEXT, NULL::SMALLINT, ARRAY[]::TEXT[], '2021-10-07T00:00:00+00:00'::TIMESTAMPTZ, '3c405f6d0b1b09ef28e968373cdce21dc1e8d5a661bfe803ed14ff1449b3b5d3'::TEXT, ARRAY[1032]::BIGINT[]),
    (311::BIGINT, 'La verdad no es tan malo como parece, sin embargo si puede meter con otro hágalo, son muchas tareas en poco tiempo y el examen final es muy difícil.'::TEXT, 4.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, '90'::TEXT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Requiere mucha lectura', 'Da crédito extra']::TEXT[], '2021-09-02T00:00:00+00:00'::TIMESTAMPTZ, '834903ad5687fd0561e658e6a5c418952ab6b89dbbe4dd5455ad5566dcb45c29'::TEXT, ARRAY[1032]::BIGINT[]),
    (311::BIGINT, 'Es un buen profesor. Se aprende bastante pero hay que ponerle. Con entregar todas las tareas y que estén aceptables se pasa sobrado junto con los extras.'::TEXT, 4.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, '85'::TEXT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Requiere mucha lectura', 'Deja trabajos largos']::TEXT[], '2021-07-27T00:00:00+00:00'::TIMESTAMPTZ, '4e90c2a139b2a04bf29572afbf87701e453463a0098f53332a960aab24145d34'::TEXT, ARRAY[1017]::BIGINT[]),
    (311::BIGINT, 'Un profesor muy malo arrogante, nunca ha trabajado en algo que no sea ser profesor, no sabe como es la calle, complejidad innecesaria para un curso que no importa realmente cuando se graduen. lo ideal es buscar otra opción y pasar relajado.'::TEXT, 4.0::NUMERIC(3,1), 4.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, '85'::TEXT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Deja trabajos largos', 'Exámenes retadores']::TEXT[], '2021-07-23T00:00:00+00:00'::TIMESTAMPTZ, '7c03ef41bbc253f80d79b9fbf1f3ac27eecca5eb55ef37d054b56cb6f1812144'::TEXT, ARRAY[2918]::BIGINT[]),
    (311::BIGINT, 'Lecturas cada semana, tareas difíciles las cuales se deben trabajar apenas se dejan para salir bien. Pulseen las tareas, entréguenlas aunque no este completas. El ultimo examen cuesta 30% de la nota y es difícil.'::TEXT, 4.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, '85'::TEXT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Requiere mucha lectura', 'Da crédito extra']::TEXT[], '2021-07-06T00:00:00+00:00'::TIMESTAMPTZ, 'a191be83a7f8873d439bf5ff4fefd235a67e5b111f08ef2fd0860c3e80835bc3'::TEXT, ARRAY[1032]::BIGINT[]),
    (311::BIGINT, 'La mayoria de las personas dicen que nunca matriculen con el. Sin embargo, sus cursos solo requieren trabajo. Deja unas 4 o 5 lecturas y una tarea programada en asm. Si una hace todo lo que le piden aunque no se perfecto va a conseguir una buena nota. Da muchos puntos extras y se aprende bastante'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, '90'::TEXT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Requiere mucha lectura', 'Da crédito extra']::TEXT[], '2021-06-24T00:00:00+00:00'::TIMESTAMPTZ, '947a3ef99ac05715b405451e30bb5f68f201e173b35924912447bc541c5fbe54'::TEXT, ARRAY[1032]::BIGINT[]),
    (311::BIGINT, 'Buen profe, tuanis. Es de ponerle como todo'::TEXT, 10.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, '85'::TEXT, NULL::SMALLINT, ARRAY['Muy cómico', 'Inspirador', 'Clases largas']::TEXT[], '2021-05-14T00:00:00+00:00'::TIMESTAMPTZ, '33375dd4fd1cb92be93291826d9453740c2e46fc90526859587034ae2c7f3d6d'::TEXT, ARRAY[1017]::BIGINT[]),
    (311::BIGINT, 'Es un muy buen profesor y persona. Solo hay un examen que es el examen final, y si hace las tareas lo va a poder hacer bien. Da un montón de puntos extra que ayudan mucho. Además sus asistentes son muy buenas personas.'::TEXT, 4.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, '100'::TEXT, NULL::SMALLINT, ARRAY['Muy cómico', 'Da crédito extra', 'Brinda apoyo']::TEXT[], '2021-01-31T00:00:00+00:00'::TIMESTAMPTZ, '5ef8c9ff2342099680dc9b168aca3a7fd42e12f0fed0d8d095f3d6daeafb2289'::TEXT, ARRAY[1032]::BIGINT[]),
    (311::BIGINT, '(virtual) para ser un curso de 4 créditos da una cantidad insana de tareas. Las lecturas resultan mucha trabajo para muy poco porcentaje. El ritmo es muy pesado con proyectos programados semanales. Lo bueno sería que hay muchas actividades extra y saca nuevas al final para pasar gente.'::TEXT, 4.0::NUMERIC(3,1), 4.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, '100'::TEXT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Requiere mucha lectura', 'Da crédito extra']::TEXT[], '2021-01-28T00:00:00+00:00'::TIMESTAMPTZ, 'bf40aa1e51445b4ba5d87ad332c64a2cf3d0f9c74c9e4b9894196d72e9b150f5'::TEXT, ARRAY[1032]::BIGINT[]),
    (311::BIGINT, 'Cree que uno ya sabe todo, por lo que no explica nada. Deja demasiadas tareas. Es demasiado difícil pasar con él.'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULL::TEXT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Da crédito extra', 'Deja trabajos largos']::TEXT[], '2020-12-28T00:00:00+00:00'::TIMESTAMPTZ, 'b1faa525c22915dae1f54affd67f5b5b0694377feb398f2e8ba558664f0bedf0'::TEXT, ARRAY[1032]::BIGINT[]),
    (311::BIGINT, 'Da explicaciones muy pobres, su modalidad de enseñanza deja mucho que desear, la verdad no se aprende casi nada en el curso, si desea aprender matricule con otro profe, de los peores profes que he tenido, caga académica innecesaria entre otras cosas.'::TEXT, 2.0::NUMERIC(3,1), 3.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, '25'::TEXT, NULL::SMALLINT, ARRAY[]::TEXT[], '2020-08-22T00:00:00+00:00'::TIMESTAMPTZ, '2e658fafc0ac1e363aee1fae393dcb486d4ad14e9d588c461306e802c586d3cb'::TEXT, ARRAY[1017]::BIGINT[]),
    (311::BIGINT, 'Califica super suave y sus asistentes también, da MUCHISIMOS puntos extra, es super buena persona y buen profesor. Sí deja bastantes tareas pero es para que uno practique para los examenes, y de las lecturas uno aprende mucho. Si usted trabaja duro él reconoce sus esfuerzos. Lo recomiendo mucho!!'::TEXT, 4.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, '100'::TEXT, NULL::SMALLINT, ARRAY['Muy cómico', 'Da crédito extra', 'Tomaría su clase nuevamente']::TEXT[], '2020-08-20T00:00:00+00:00'::TIMESTAMPTZ, 'b353e983a94201f9204730edb9bfc958e8ea0e4d0078c8118251e5205872f138'::TEXT, ARRAY[1017]::BIGINT[]),
    (311::BIGINT, 'Un pacho de profe, cuenta hasta lo que no precisa. Puede ser muy aburrido o entretenido según como lo veas, si entregas todos los trabajos fijo pasas, tomando en cuenta los extras por supuesto. Llevar un curso con Kirstein es tedioso, pero seguro si le pones y lo peor es que pasa casi sin aprender.'::TEXT, 6.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, '70'::TEXT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Muchas tareas', 'Tomaría su clase nuevamente']::TEXT[], '2020-08-18T00:00:00+00:00'::TIMESTAMPTZ, '7888a7b151a1fbf03ea9799153d83106c601e18558a96abd930191bb3556381a'::TEXT, ARRAY[1017]::BIGINT[]),
    (311::BIGINT, 'Deja muchas lecturas todas las semanas. Los exámenes son muy largos, se puede durar todo el día y, aún así, no terminarlos. Enseña cosas que no tienen nada que ver con la carrera y que son totalmente inútiles. Da muchos puntos extra.'::TEXT, 2.0::NUMERIC(3,1), 5.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, '90'::TEXT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Muchas tareas', 'Requiere mucha lectura']::TEXT[], '2020-08-13T00:00:00+00:00'::TIMESTAMPTZ, '615c00500fe52e997b4088be493fa1e2613f635573e0f28d643fdb033341e1be'::TEXT, ARRAY[1017]::BIGINT[]),
    (311::BIGINT, 'Vea, si usted es organizado y sabe llevar los resúmenes y tareas al día, le va bien. Las tareas son muy largas, a veces no valen la pena hacerlas, eso sí, sí las hace, va preparado para el examen. Si hay algo que le recalco al profe, es que es muy CLARO con lo que quiere, se aprende mucho. Pandemia'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULL::TEXT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Aspectos de calificación claros', 'Deja trabajos largos']::TEXT[], '2020-07-30T00:00:00+00:00'::TIMESTAMPTZ, 'bd8f3ade701dd54b9d7530f43a65f15054108dbe71d711fd964f2e420d58728d'::TEXT, ARRAY[1017]::BIGINT[]),
    (311::BIGINT, 'Si llevan un horario muy apretado no lleven con él. Sin embargo también tiene sus cosas, si pueden llevar con otro profe háganlo.'::TEXT, 4.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULL::TEXT, NULL::SMALLINT, ARRAY[]::TEXT[], '2020-06-09T00:00:00+00:00'::TIMESTAMPTZ, 'eb723e03ef82ca7b6d050308850e2b9036e0977ac0a6756a8ab6f69c56dbc650'::TEXT, ARRAY[1017]::BIGINT[]),
    (311::BIGINT, 'La definición de "mal profesor" lleva el nombre de este señor a la par, 0 competencia para dar clases, cree que ud sólo lleva su materia. Por favor que alguien le diga que presionar al estudiante tanto no es sinónimo de enseñar.'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, '70'::TEXT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Muchas tareas', 'Asistencia obligatoria']::TEXT[], '2020-05-20T00:00:00+00:00'::TIMESTAMPTZ, 'b7b336c7044e589e9b0627ce9a573ec1e2986ce65bca506c8078561a1cb3e1dc'::TEXT, ARRAY[1032]::BIGINT[]),
    (311::BIGINT, 'Es uno de los mejores profesores de la escuela de computación . Sabe muchísimo y se aprende bastante. Hay que esforzarse bastante debido a que el curso demanda mucha dedicación y el profe no le regala nada a nadie .'::TEXT, 2.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, '70'::TEXT, NULL::SMALLINT, ARRAY['Aspectos de calificación claros', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2019-12-04T00:00:00+00:00'::TIMESTAMPTZ, '0715fe599430af48c90a92eebd99828c4d8e891b705736023121bfb13affee6a'::TEXT, ARRAY[1017]::BIGINT[]),
    (311::BIGINT, 'Explica súper mal y además es muy grocero. Hay que leer mucho y las larguísimas tareas no enseñan tanto como la practica, cosa que él no hace. Piensa que uno solo lleva su curso, exámenes de 150 preguntas y de 6 horas. No me gustó su método de enseñanza.'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, '85'::TEXT, NULL::SMALLINT, ARRAY['Requiere mucha lectura', 'Deja trabajos largos', 'Exámenes retadores']::TEXT[], '2019-11-06T00:00:00+00:00'::TIMESTAMPTZ, '11883a6d6f03227c76bbce83826c5df9787ec047de53081877cc876098bb9ea9'::TEXT, ARRAY[1017]::BIGINT[]),
    (311::BIGINT, 'Si decide llevar con él va a aprender demasiado, es rudo y demanda muchísimo tiempo, pero si realiza todas las tareas y resúmenes de lecturas de fijo pasa. Durante todo el semestre hay oportunidades de ganar puntos extras, aproveche eso y al final la nota le va a aumentar como en un 15%.'::TEXT, 2.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, '85'::TEXT, NULL::SMALLINT, ARRAY['Requiere mucha lectura', 'Da crédito extra', 'Deja trabajos largos']::TEXT[], '2019-06-24T00:00:00+00:00'::TIMESTAMPTZ, 'a44f0d1879f4bfc70384b087728b2b51a579baba036f32312348e7a94d4fe694'::TEXT, ARRAY[1017]::BIGINT[]),
    (311::BIGINT, 'Se aprende un montón pero es muy duro, muchos resúmenes, tareas extensas que consumen mucho tiempo, los exámenes son domingos, y usualmente duran 8 horas. Si entrega TODO y hace los puntos extra pasa sin problemas. Si de verdad quiere aprender entonces matricule con él, pero va a sufrir.'::TEXT, 2.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, '85'::TEXT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Deja trabajos largos', 'Exámenes retadores']::TEXT[], '2019-06-10T00:00:00+00:00'::TIMESTAMPTZ, '4a509bfbcc877522087d4f71085dbcd7471b91b96701ebdc291498cdba48b331'::TEXT, ARRAY[1017]::BIGINT[]),
    (311::BIGINT, 'Si puede evitarlo hagalo , mucho gtabajo no se aprende'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, '70'::TEXT, NULL::SMALLINT, ARRAY['Requiere mucha lectura', 'Da crédito extra']::TEXT[], '2018-12-05T00:00:00+00:00'::TIMESTAMPTZ, '16910e941acd6c9be481a167d13e1c871c4520600ddcb2e2c8f07f9143e94777'::TEXT, ARRAY[1017]::BIGINT[]),
    (311::BIGINT, 'Lenguajes es su curso más "fácil", Compi es más pasable que en FOC. Si hace los resúmenes (que permite escoger la cantidad) y las progras cortas/etapas las saca a lo mayor posible, se pasa el curso; recuerde que están además los puntos extra. Puede hacer 1 ó 2 exámenes.'::TEXT, 6.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, '85'::TEXT, NULL::SMALLINT, ARRAY['Asistencia obligatoria', 'Respetado por los estudiantes', 'Da crédito extra']::TEXT[], '2018-06-25T00:00:00+00:00'::TIMESTAMPTZ, '8eb90b99cbfccf300bcb9ed12270ee23948218f87c75523ad68a947325245b02'::TEXT, ARRAY[1045, 1054]::BIGINT[]),
    (311::BIGINT, 'Es un buen profersor, parecen muchos trabajos pero es solo tener consistencia y llegar al final, cualquiera que presente todas las cosas termina pasando'::TEXT, 4.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, '90'::TEXT, NULL::SMALLINT, ARRAY['Muy cómico', 'Muchas tareas', 'Deja trabajos largos']::TEXT[], '2018-06-25T00:00:00+00:00'::TIMESTAMPTZ, '0f2af44755643e1216b52c827a5c8a7b6c0d9a35b905e63bc3a0e315c3285e73'::TEXT, ARRAY[1054]::BIGINT[]),
    (311::BIGINT, 'Es muy duro llevar con el pero es excelente profe se aprende, pero tome su curso como de 6 créditos, recomendado pero es muy duro'::TEXT, 2.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULL::TEXT, NULL::SMALLINT, ARRAY[]::TEXT[], '2018-06-24T00:00:00+00:00'::TIMESTAMPTZ, 'aa47de6e237c3026ac5c048c18e91f87095388967189bcb58f2361c4b7922a79'::TEXT, ARRAY[1017]::BIGINT[]),
    (311::BIGINT, 'Podrá dar mucho trabajo y que las tareas y exámenes sean difíciles, pero las bases son muy buenas'::TEXT, 6.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, '70'::TEXT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Deja trabajos largos', 'Tomaría su clase nuevamente']::TEXT[], '2018-06-07T00:00:00+00:00'::TIMESTAMPTZ, 'ca6ce16ea4ff8de5ccb91ac3192c49b3ad044f0bca25000ac1d2609491b578fc'::TEXT, ARRAY[1017]::BIGINT[]),
    (311::BIGINT, 'Ninguno'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, '65'::TEXT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Muchas tareas', 'Asistencia obligatoria']::TEXT[], '2018-05-30T00:00:00+00:00'::TIMESTAMPTZ, 'e912c7c6d4f128f54627a71a1b67d90837fb23b684709f16b6b6453efca86499'::TEXT, ARRAY[1017]::BIGINT[]),
    (311::BIGINT, 'Ninguno'::TEXT, 4.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULL::TEXT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Requiere mucha lectura', 'Deja trabajos largos']::TEXT[], '2018-05-25T00:00:00+00:00'::TIMESTAMPTZ, '4f8cb5a7d19f6d0b84c8065e42037c570abce70d06c6419c4d19b5b2f1753912'::TEXT, ARRAY[1017]::BIGINT[]),
    (311::BIGINT, 'Pésimo profesor.'::TEXT, 6.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, '80'::TEXT, NULL::SMALLINT, ARRAY['Clase fácil', 'Asistencia obligatoria']::TEXT[], '2018-05-23T00:00:00+00:00'::TIMESTAMPTZ, '2e129a4ca4ff1059121567de7128bbd083ffa1f1d15b14445d66bb1a07e10075'::TEXT, ARRAY[1032]::BIGINT[]),
    (311::BIGINT, 'El curso es súper duro, deja demasiados trabajos, hay que leer muchísimo, como persona súper buena gente como profesor puede llegar a ser bastante odioso, siempre hace muchísimas preguntas y para pasar no falte a clases y haga todo lo extra posible'::TEXT, 4.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, '80'::TEXT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Requiere mucha lectura', 'Da crédito extra']::TEXT[], '2018-01-24T00:00:00+00:00'::TIMESTAMPTZ, '6f3a33b6a1bd6f9eac0ec24ca005f0c91fe4c1703f66f0b141fc673af510d4c6'::TEXT, ARRAY[1045]::BIGINT[]),
    (311::BIGINT, 'El profe como persona no es mala gente, eso sí, todo depende de usted. Si quiere pasar tome apuntes, y siempre haga los puntos extra y todos los resúmenes. Nunca falte a clases.'::TEXT, 2.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, '70'::TEXT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Muchas tareas', 'Requiere mucha lectura']::TEXT[], '2018-01-16T00:00:00+00:00'::TIMESTAMPTZ, '86133173ccc3328b4764bf474c9a941e234ed231dfffe1b7205b7edefb0d5760'::TEXT, ARRAY[1045]::BIGINT[]),
    (311::BIGINT, 'Es dificil pero es muy pasable si usted hace las tareas desde el primer dìa. Clases super entretenidas, tareas interesantes y dificiles, muchas lecturas y resumenes con gran valor de la nota. Le interesa dar clases pero no le gusta atender estudiantes fuera de clases, ayuda con trabajos de pts extra'::TEXT, 2.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, '50'::TEXT, NULL::SMALLINT, ARRAY[]::TEXT[], '2017-06-30T00:00:00+00:00'::TIMESTAMPTZ, 'f3104a58691823bf788253c53ab0510e82392aacd848039a14f0a1b0d929a133'::TEXT, ARRAY[1045]::BIGINT[]),
    (311::BIGINT, 'Es un profesor que deja muchisimos trabajos, esto es bueno ya que te permite entender la materia que da y te prepara para sus examenes (los cuales llegan a ser de hasta 8 horas). Tareas y lecturas todas las semanas. Ayuda a prepararse para el resto de la carrera'::TEXT, 4.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, '90'::TEXT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Clases largas', 'Deja trabajos largos']::TEXT[], '2017-06-27T00:00:00+00:00'::TIMESTAMPTZ, '9ed7830b00831eb981f0766e2996502a3a6d324623eeb1b9d964a101e28e1b50'::TEXT, ARRAY[1017]::BIGINT[]),
    (311::BIGINT, 'El que mejor lo prepara a uno para la dificultad que vendrá a lo largo de la carrera. Siempre hay trabajos que hacer, es bien difícil mantenerse al día. Al final uno siente como que todo el esfuerzo valió la pena y que aprendió en un semestre más que en toda su vida. Al final regala como 10pts extra'::TEXT, 2.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, '75'::TEXT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Requiere mucha lectura', 'Exámenes retadores']::TEXT[], '2017-06-27T00:00:00+00:00'::TIMESTAMPTZ, '119f98fb1ab89c3b49219820263776e50a5f72be895433ff1fd9cb49b7dda127'::TEXT, ARRAY[1017]::BIGINT[]),
    (311::BIGINT, 'Un curso bastante demandante de tiempo, deja resúmenes todas las semanas y tareas "cortas" cada 2 o 3 semanas. Las clases son excelentes y programa ejercicios que luego salen en los quices. Se aprende bastante pero es un curso de un par de créditos más.'::TEXT, 4.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, '85'::TEXT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Asistencia obligatoria', 'Clases excelentes']::TEXT[], '2017-06-26T00:00:00+00:00'::TIMESTAMPTZ, 'dfe5963e95925c5eb611e2cb991f353afcd96f4e0081fe7ec2aef7beddc307d4'::TEXT, ARRAY[1045]::BIGINT[]),
    (311::BIGINT, 'Los exámenes son muy difíciles pero si se hacen los trabajos (aunque son muchos) y llega hasta el final del semestre, el profe le ayuda. Da muchos puntos extra y los estudiantes hacen preguntas de los exámenes. Prepárese para trabajar mucho.'::TEXT, 4.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULL::TEXT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Da crédito extra', 'Exámenes retadores']::TEXT[], '2017-06-23T00:00:00+00:00'::TIMESTAMPTZ, '82a247bea486a3d5e6f34f8ab1ff12b01df2d82811ab8f3997d9615609741afc'::TEXT, ARRAY[1017]::BIGINT[]),
    (311::BIGINT, 'Pésimo! Le gusta basurear a los estudiantes, no hay respeto en las clases y los exámenes son lo peor, un domingo y son de 180 preguntas y así. ¿En la cabeza de quien cabe que es un buen sistema de evaluación ese? No lo recomiendo para nada.'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULL::TEXT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Requiere mucha lectura', 'Exámenes retadores']::TEXT[], '2017-06-23T00:00:00+00:00'::TIMESTAMPTZ, 'e6dc96a8ed0bcfebb9df45be5f87c56572455a80bd56cc247d2ccd751f681699'::TEXT, ARRAY[1032]::BIGINT[]),
    (311::BIGINT, 'Sabe mucho, pero da por un hecho que todos entienden igual de rápido, ridiculiza a los alumnos y no se aprende casi nada por lo saturado que se está haciendo trabajos y ejercicios inventados por él que al final solo confunden más. Si lleva bloque completo no le recomiendo matricular con este profe'::TEXT, 2.0::NUMERIC(3,1), 3.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, '70'::TEXT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Requiere mucha lectura', 'Deja trabajos largos']::TEXT[], '2017-06-21T00:00:00+00:00'::TIMESTAMPTZ, '1ca1ce3c35b2cff3d45c63a859a1b85bbd0f0b2bef7cdd7c68e041b621c3ddba'::TEXT, ARRAY[1017]::BIGINT[]),
    (311::BIGINT, 'El profe sabe bastante y las clases son buenas. Muchos trabajos y resumenes que si uno se adapta puede pasar facilmente. Existen muchos puntos extras que dan mas oportunidades y si uno demuestra esfuerzo e interes él hará lo posible para que pase o que le quede al menos una nota buena'::TEXT, 4.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, '70'::TEXT, NULL::SMALLINT, ARRAY[]::TEXT[], '2017-06-16T00:00:00+00:00'::TIMESTAMPTZ, '52fa45879497d01d666d898fd2aa1b47b3e5f8274b6a8e435f5030488f8cacaa'::TEXT, ARRAY[1054]::BIGINT[]),
    (311::BIGINT, 'Ninguno'::TEXT, 2.0::NUMERIC(3,1), 4.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, '70'::TEXT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Muchas tareas', 'Requiere mucha lectura']::TEXT[], '2017-06-16T00:00:00+00:00'::TIMESTAMPTZ, 'ba3bba9110d4d1950a159a1028d30bbcb7a1f8b4bbbadda50fd29cf746e2e167'::TEXT, ARRAY[1054]::BIGINT[]),
    (311::BIGINT, 'Si a usted le parece bien que un profesor haga exámenes de 6 o 7 horas, que lo tenga de esclavo todo el semestre haciendo resúmenes y que por medio de su sistema de "puntos extra" intente comprar a los estudiantes para que hagan las cosas que ÉL como profesor debe hacer, adelante, matricule con él.'::TEXT, 2.0::NUMERIC(3,1), 5.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, '60'::TEXT, NULL::SMALLINT, ARRAY['Muchas tareas']::TEXT[], '2017-01-31T00:00:00+00:00'::TIMESTAMPTZ, '41cfd2654cf3d1a60a6a61465d53664b5430bd0739dc9cb01b67190f01d58039'::TEXT, ARRAY[1032]::BIGINT[]),
    (311::BIGINT, 'Uno de los cursos más difíciles que él da, por lo que si FOC es pesado este curso lo es aún más. Enfocado casi 100 % en ASM. Se aprende aunque sus clases son iguales en cualquiera de los cursos que da. Como siempre, da muchos pts extra, deja una masiva cantidad de tareas y parciales los domingos.'::TEXT, 2.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, '70'::TEXT, NULL::SMALLINT, ARRAY[]::TEXT[], '2017-01-29T00:00:00+00:00'::TIMESTAMPTZ, '735e953d4026c049adce71c4c86804d2eeff13fd5bd6b32d7eb47a51000c3b57'::TEXT, ARRAY[1032]::BIGINT[]),
    (311::BIGINT, 'Mucha carga académica, lo que llega a quitar interés. Aunque sabe mucho, los programas que usa son bastante obsoletos'::TEXT, 4.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, '70'::TEXT, NULL::SMALLINT, ARRAY['Exámenes retadores']::TEXT[], '2017-01-27T00:00:00+00:00'::TIMESTAMPTZ, 'e3c1f6b17505a7876533ccb327162555728ffb04f8b9931599d8f938a1a7967f'::TEXT, ARRAY[1017]::BIGINT[]),
    (311::BIGINT, 'Ninguno'::TEXT, 6.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, '85'::TEXT, NULL::SMALLINT, ARRAY[]::TEXT[], '2017-01-18T00:00:00+00:00'::TIMESTAMPTZ, '46af3fddf6c2fd06df377a556b33fb6a86486403376af48777ecefcd9a58e3f0'::TEXT, ARRAY[1045]::BIGINT[]),
    (311::BIGINT, 'Flojo, desactualizado, sus cursos se pasan en solo manejando unos cuantos resúmenes, le falta conocimiento en lenguajes y paradigmas, y se mantiene con su argolla siempre. Pase su curso sin hacer el ultimo examen por que descifre su formula (y el trato de dejarme pero no pudo)'::TEXT, 6.0::NUMERIC(3,1), 3.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, '80'::TEXT, NULL::SMALLINT, ARRAY[]::TEXT[], '2017-01-18T00:00:00+00:00'::TIMESTAMPTZ, '2e8f49391df72fb1f24eb1f543997385fd43c75351efa28c9a70fe60e2f6fac1'::TEXT, ARRAY[1045]::BIGINT[]),
    (311::BIGINT, 'Deja un montón de lecturas cada semana, algunas son difíciles de comprender. Las tareas son de dificiltad moderada. No explica mal pero tampoco es el mejor profesor del mundo explicando. Enseñando ensamblador es muy malo. Da como 15% en puntos extras y eso salva a muchos. Exámenes en domingo.'::TEXT, 10.0::NUMERIC(3,1), 5.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, '70'::TEXT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Requiere mucha lectura', 'Da crédito extra']::TEXT[], '2016-12-03T00:00:00+00:00'::TIMESTAMPTZ, 'bf327bc4a8ed53783cd8cfcc41c36499bb4c0b85ac2754d77d671abf3885a7a5'::TEXT, ARRAY[1017]::BIGINT[]),
    (311::BIGINT, 'En el primer examen nos entraban 90 capítulos más lo visto en clase... Lecturas TODAS las semanas, resúmenes, etc. requiere muuuucho tiempo. Hay poca retroalimentación. Lo único bueno es que da puntos extra hasta por respirar, pero hay que hacer todo. De 75 pasé a 90 con puntos extra :)'::TEXT, 2.0::NUMERIC(3,1), 3.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, '90'::TEXT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Requiere mucha lectura', 'Asistencia obligatoria']::TEXT[], '2016-10-21T00:00:00+00:00'::TIMESTAMPTZ, '84772815533638a505826feb281c1133e6f54a9153b06081d79ee4625e8dcf33'::TEXT, ARRAY[1045]::BIGINT[]),
    (311::BIGINT, 'dos cursos lleve con el, de las 2 horas de clases, pasa la primera hora preparando lo que va a hablar en la segunda hora, y en la segunda hora se pasa quejando que el tiempo no alcanza, te hara venir fines de semana a reponer clases por su falta organizacional, te hace aprender cosas inutiles que no te serviran para nada en tu vida, se pone a inventar numeraciones tontas que solo a el le importan y lo peor de todo es que te las tienes que aprender, como si en un trabajo te van a preguntar si conoces que son los "numedreces"(si asi de tontos son los nombres), un profesor en de verdad necesita actualizarse porque las cosas que enseña son del siglo pasado, sinceramente, no se los recomiendo para nada. (PD: no piensen que soy un resentido porque ambos cursos se los pase con buena nota.)'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, '85'::TEXT, NULL::SMALLINT, ARRAY['Requiere mucha lectura', 'Asistencia obligatoria', 'Exámenes retadores']::TEXT[], '2016-06-23T00:00:00+00:00'::TIMESTAMPTZ, 'd5220bb681450dcc2ab024f4baeeb30ff1f21a950ee698db902e9421ab19e03b'::TEXT, ARRAY[1054]::BIGINT[]),
    (311::BIGINT, 'Es un curso díficil, uno aprende a la fuerza pero lo hace. Las clases son dificiles de entender pero explica muy bien la materia. Los examenes son muy largos (6-8 h), las tareas en general son dificiles. Da muchos puntos extra por todo y tiene mucha piedad. Es un muy buen profe, pero hay que bretear'::TEXT, 4.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, '70'::TEXT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Da crédito extra', 'Tomaría su clase nuevamente']::TEXT[], '2016-06-23T00:00:00+00:00'::TIMESTAMPTZ, '89fd84f93f4247e8f38d8b9955680715ae9b2b42ca2c0a8876034673e05206fd'::TEXT, ARRAY[1017]::BIGINT[]),
    (311::BIGINT, 'Es muy matado, sin embargo, sí se aprende con él. Si querés pasar, no es recomendable llevar bloque completo.'::TEXT, 2.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, '90'::TEXT, NULL::SMALLINT, ARRAY['Requiere mucha lectura', 'Deja trabajos largos', 'Exámenes retadores']::TEXT[], '2016-06-07T00:00:00+00:00'::TIMESTAMPTZ, '42d9fd19b9f8acbb07e60128e256ba41df726f9549d6802f6ce844cfc8c09a69'::TEXT, ARRAY[1017]::BIGINT[]),
    (311::BIGINT, 'Buen profesor, gracioso y buena nota El curso es muy dócil pero se aprende mucho'::TEXT, 4.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, '70'::TEXT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Requiere mucha lectura', 'Da crédito extra']::TEXT[], '2016-06-07T00:00:00+00:00'::TIMESTAMPTZ, 'c0fc406de3b20cc4c429e16b16c6226997a143021a464cd4845703fe8af97e77'::TEXT, ARRAY[1017]::BIGINT[]),
    (311::BIGINT, '¡Solo para valientes! ...que quieren morir'::TEXT, 2.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, '70'::TEXT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Deja trabajos largos', 'Exámenes retadores']::TEXT[], '2016-06-06T00:00:00+00:00'::TIMESTAMPTZ, '3800923eb995dcaf156dcd1642c5a62ab9898d0c163e23c7823ccab6381d9bde'::TEXT, ARRAY[1017]::BIGINT[]),
    (311::BIGINT, 'De los peores del TEC, es irrespetuoso, cae mal y no se le entiende nada, en media clase se pone a hablar de los hijos hasta el cansancio y luego anda presionando porque falta materia, hace exámenes de 180 preguntas de marque con X que no se entiende ni mierda.'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULL::TEXT, NULL::SMALLINT, ARRAY[]::TEXT[], '2016-06-04T00:00:00+00:00'::TIMESTAMPTZ, 'edd10ad7fd9460a03561be9a89adb2296e31d6b3bfc8bef4b0b5d7c5ac8e0677'::TEXT, ARRAY[1032]::BIGINT[]),
    (311::BIGINT, 'Un profesor que vive en el siglo pasado, toda la gente que dice que "se aprende" con el, que me diga que cosas de las que aprendieron en sus clases les servirán para sus vidas laborales,no lo recomiendo para nada y pierde la mitad de cada clase hablando mier.. y despues repone sabados completos.....'::TEXT, 2.0::NUMERIC(3,1), 4.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, '85'::TEXT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Requiere mucha lectura']::TEXT[], '2016-04-13T00:00:00+00:00'::TIMESTAMPTZ, 'f9b8b18a3b249433192862ab112965e3cedca02647dd93fa8cd4285ee8d99878'::TEXT, ARRAY[1045]::BIGINT[]),
    (311::BIGINT, 'Es un profesor con el que se aprende o se aprende. Pero si llevas bloque completo, va a ser una tortura. Todas las semanas deja lecturas con las que hay que entregar un resumen por cada una. Además la cantidad de materia que te mete es algo inhumano. Tareas largas y difíciles. Exámenes de 7 horas.'::TEXT, 2.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULL::TEXT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Requiere mucha lectura', 'Deja trabajos largos']::TEXT[], '2016-04-02T00:00:00+00:00'::TIMESTAMPTZ, '5d0b5ac84a06516631fb4d88e72a2bb0337bfd40be41f24bc48c240e8397f25b'::TEXT, ARRAY[1017]::BIGINT[]),
    (311::BIGINT, 'Ninguno'::TEXT, 2.0::NUMERIC(3,1), 5.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, '75'::TEXT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Da crédito extra', 'Exámenes retadores']::TEXT[], '2016-02-26T00:00:00+00:00'::TIMESTAMPTZ, 'ef0248eb036c84c9d74e87da06d4d8189b34d62c8ed6658e76a5e516242fb67f'::TEXT, ARRAY[1017]::BIGINT[]),
    (311::BIGINT, 'Este curso dependerá de usted tener tiempo y una buena pareja de trabajo (o ser una persona extremadamente productiva). Si falla en alguno de los dos, ni siquiera piense en pasarlo.'::TEXT, 4.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, '95'::TEXT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Requiere mucha lectura', 'Asistencia obligatoria']::TEXT[], '2016-02-03T00:00:00+00:00'::TIMESTAMPTZ, 'cc112e220f7d9edc146bdaf33e6e189952708272738ae090584b8bb63d67fcf3'::TEXT, ARRAY[1054]::BIGINT[]),
    (311::BIGINT, 'Un profe que tiene el don de la enseñanza, PERO no es de los que aclaran dudas, o si lo hacen pero no sin antes burlarte de vos XD, es una materia que no creo que debiera ser tan difícil (como 8 créditos), pero si pueden matricular con él, habrá sido una de las mejores inversiones para su carrera'::TEXT, 2.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, '95'::TEXT, NULL::SMALLINT, ARRAY[]::TEXT[], '2016-01-29T00:00:00+00:00'::TIMESTAMPTZ, '96a4f30c30526ccc94d72497514547ecb7107a0fe319a707fbd84ef54d65fc4f'::TEXT, ARRAY[2918]::BIGINT[]),
    (311::BIGINT, 'Solo con Kirstein vas a poder trabajar en mas de 10 lenguajes en un solo semestre :)'::TEXT, 4.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, '90'::TEXT, NULL::SMALLINT, ARRAY[]::TEXT[], '2016-01-23T00:00:00+00:00'::TIMESTAMPTZ, '19fd5691943ebd5713fe14aa7d675a469c3c53df14c9b46edf2916c32ae8b307'::TEXT, ARRAY[1045]::BIGINT[]),
    (311::BIGINT, 'Es buen profe, las clases son entretenidas y da bastantes puntos extra que pueden salvar la tanda. Sin embargo hay que ponerle bastante y nunca confiarse. Los trabajos son bastantes, muy pesados y nunca hay que dejarlos para lo último.'::TEXT, 4.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULL::TEXT, NULL::SMALLINT, ARRAY[]::TEXT[], '2016-01-20T00:00:00+00:00'::TIMESTAMPTZ, '4db5d13439ffaf1694b7d5ab8d4d9364dfab272fc9ae840df3acf5c36c5316e6'::TEXT, ARRAY[1017]::BIGINT[]),
    (311::BIGINT, 'Duro, mucho trabajo, pero es pasable. Enseña bien, organizado, puntual. Examenes largos. Nunca desperdiciar ningun punto extra. Progras entretenidas. Demasasiada materia. En mi opinión debería de actualizar al curso.'::TEXT, 6.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, '100'::TEXT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-12-02T00:00:00+00:00'::TIMESTAMPTZ, '3323940bf8ff4fc386d331750c5dfacac4fe18cc5136daba5ef0b9a57d658fdd'::TEXT, ARRAY[1045]::BIGINT[]),
    (311::BIGINT, 'Clase muy pesada,quita demasiado tiempo con tantas lecturas y tareas, por lo que no da tiempo para los otros cursos, por lo cual no lo recomiendo con bloque completo. Sin embargo es un excelente profesor y el conocimiento que se obtiene lo vale.'::TEXT, 4.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULL::TEXT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-11-15T00:00:00+00:00'::TIMESTAMPTZ, '1017659ab94a16c44aab815abc4818bb5a65a44d2f5b79ca93676a1c5064458e'::TEXT, ARRAY[1017]::BIGINT[]),
    (311::BIGINT, 'Si quieres pasar el resto de cursos del semestre no lleves con Kirstein.'::TEXT, 2.0::NUMERIC(3,1), 4.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, '70'::TEXT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-11-06T00:00:00+00:00'::TIMESTAMPTZ, '6f0d9f8579e584390d94b0b4bf5a0cbb077ead2999df6ea7311cddc28eb75cd2'::TEXT, ARRAY[1017]::BIGINT[]),
    (311::BIGINT, 'Ninguno'::TEXT, 2.0::NUMERIC(3,1), 5.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, '80'::TEXT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-06-28T00:00:00+00:00'::TIMESTAMPTZ, 'd9e4548304e1c0c761ea91c1949bf94401613b7cf11593c54236406840074fee'::TEXT, ARRAY[1017]::BIGINT[]),
    (311::BIGINT, 'Este profe es uno de los mejores profes que he tenido en computacion, lo obliga a leer pero esto es por el bien de uno, se hacen examenes los domingos pero eso es lo de menos, se aprende demaciado, es puntual y realiza ejemplos en clase que ayudan a comprender la materia, se le entiende'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, '90'::TEXT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-06-28T00:00:00+00:00'::TIMESTAMPTZ, 'd7bef23079225242987a4df5d67485f7eb18c3c10cba7238a9f7cda7579f8ec2'::TEXT, ARRAY[1017, 1032]::BIGINT[]),
    (311::BIGINT, 'Llevar un curso con él es súper pesado. Lecturas y tareas todas las semanas, exámenes de literalmente 5 horas los domingos y a veces hasta feriados, las pruebas cortas no tienen nada de cortas. Sin embargo, de que se aprende, se aprende. Volvería a llevar un curso con él. Muy bueno y sabe un montón.'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, '90'::TEXT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-06-24T00:00:00+00:00'::TIMESTAMPTZ, '1f2ebe555d22d57c787b11f2cb9beee9bf57cd9aad97cc01922905170634f937'::TEXT, ARRAY[1017]::BIGINT[]),
    (311::BIGINT, 'Los cursos con Kirstein son pesados, muchas lecturas, exámenes los domingos de más de 5 horas y las tareas tienen un grado de dificultad moderado. Sin embargo, queriendo o no, sale aprendiendo montones (es muy buen profe).'::TEXT, 4.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, '80'::TEXT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-06-20T00:00:00+00:00'::TIMESTAMPTZ, '68c1c65affd1170f63c5d01ebb1d93b5d42fad53a26870fb29be550a9030f32e'::TEXT, ARRAY[1017, 1032, 1045]::BIGINT[]),
    (311::BIGINT, 'El profesor explica bastante. Con él se aprende demasiado. Hay que hacer muchos "resúmenes" (El curso se basa en los mismos). No hay clase e la cual nunca uno se ría, ya que es muy bromista.Los exámenes son super largos (6 hrs), pero tampoco imposibles. Regala muchos puntos extra, si uno se los gana'::TEXT, 4.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, '90'::TEXT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-06-20T00:00:00+00:00'::TIMESTAMPTZ, '89015e7cde4c7967c697c441a9bc428006682a5379c74d7548e38a8e8a927fd2'::TEXT, ARRAY[1017, 1045]::BIGINT[]),
    (311::BIGINT, 'Explica muy bien, muy completo el curso, se aprende bastante'::TEXT, 6.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, '90'::TEXT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-06-02T00:00:00+00:00'::TIMESTAMPTZ, '8f9a181939e0f875b4a4617b89951199001cf854d05f9bf84fdb386fa397b644'::TEXT, ARRAY[1045]::BIGINT[]),
    (311::BIGINT, 'Ninguno'::TEXT, 2.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULL::TEXT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-05-28T00:00:00+00:00'::TIMESTAMPTZ, '858c7de2de6750cf9b27acfea7a9fa554807510186b3ff6faf0f08b481504f08'::TEXT, ARRAY[1017]::BIGINT[]),
    (311::BIGINT, 'Ninguno'::TEXT, 2.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULL::TEXT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-02-02T00:00:00+00:00'::TIMESTAMPTZ, 'a1308039291beca9ce76bde05b44cea3cfdaa812c2ed43355ebb43546cc3c67a'::TEXT, ARRAY[1017]::BIGINT[]),
    (311::BIGINT, 'Deja trabajos cada semana pero sirven para reforzar materia. Uno pasa haciendo las tareas y proyectos y no hace falta mencionar los puntos extras que pueden salvar a uno. Los examenes de 6 horas los domingos son agotados pero tampoco los hace tan imposibles para que uno se quede. Recomendado!'::TEXT, 6.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, '80'::TEXT, NULL::SMALLINT, ARRAY[]::TEXT[], '2014-11-18T00:00:00+00:00'::TIMESTAMPTZ, 'e647bcfbc30a78ff338b6903b3df0eafd2778cbb2298fd04f088d2bb529f779b'::TEXT, ARRAY[1017]::BIGINT[]),
    (311::BIGINT, 'Es un inmaduro, pero, explica bien, da ejemplos, es puntual... Si les gusta hacer exámenes los domingos o ver a un profesor comer frente a ustedes (y eructar) pueden matricular con el. Actualmente todo mundo pasa porque da como 15% extra.'::TEXT, 8.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, '35'::TEXT, NULL::SMALLINT, ARRAY[]::TEXT[], '2014-11-18T00:00:00+00:00'::TIMESTAMPTZ, 'e8f2198ce0843d798ff446342f9058c1621abbf05df2d75baccb7d929236d9e8'::TEXT, ARRAY[1032, 1045]::BIGINT[]),
    (311::BIGINT, 'Por mucho el mejor profe que he tenido, conlleva mucho sacrificio llevar un curso con él, pero al final los beneficiados somos nosotros, además los famosos puntos extra siempre son una salvada :)'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, '90'::TEXT, NULL::SMALLINT, ARRAY[]::TEXT[], '2014-11-18T00:00:00+00:00'::TIMESTAMPTZ, '217b306fce47909bd414787204e11d02cd9a056aad54496f47a06416145d0ce2'::TEXT, ARRAY[1017, 1032]::BIGINT[]),
    (311::BIGINT, 'Es buen profe, y es tuanis si uno lo lleva tuanis. Es duro, deja montones de trabajo, pero también muchos puntos extra que ayudan a pasar el curso. Es un profe muy inteligente. No es de los profes que disfrutan quedar gente, siempre espera que pase bastante gente. Pero que aprendan y le pongan ganas'::TEXT, 4.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, '80'::TEXT, NULL::SMALLINT, ARRAY[]::TEXT[], '2014-11-18T00:00:00+00:00'::TIMESTAMPTZ, 'd67b15d7518aa178d9abe18cd5e9cc4fe012e7b134bcf3e2ae06203de8342a03'::TEXT, ARRAY[1017]::BIGINT[]),
    (311::BIGINT, 'Imparte cursos que conllevan mucho trabajo, pues esa es la técnica de enseñanza de él. Se recomienda totalmente pero estar seguros que será un hecho el trabajar mucho a tráves del semestre. Como persona una teja. Contesta consultas, incita al deporte (sus famosas mejengas), es comprensivo.'::TEXT, 4.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, '100'::TEXT, NULL::SMALLINT, ARRAY[]::TEXT[], '2014-11-17T00:00:00+00:00'::TIMESTAMPTZ, '6ee4d80585d45f51ba17bd847b33dd62a49070f2b2fcc4e2cb13ed501addd5a4'::TEXT, ARRAY[1032, 1017, 1045]::BIGINT[]),
    (311::BIGINT, 'Deja una cantidad de inmensa de trabajos, y los examenes son algo difícles, se llega en un momento a saber q no se puede pasar, pero es ultra pasable gracias a los puntos extras....'::TEXT, 4.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, '75'::TEXT, NULL::SMALLINT, ARRAY[]::TEXT[], '2014-11-15T00:00:00+00:00'::TIMESTAMPTZ, '98ae7af9ad0ff0458d049380d6baf81695fea27d72d5f240993bff8099ed5364'::TEXT, ARRAY[1017]::BIGINT[]),
    (311::BIGINT, 'Kirstein explica muy bien la materia, es muy buen profe, las clases son entretenidas, deja mucho brete, los examenes son muy largos, es muy ordenado y puntual, el ayuda mucho con puntos extras, se aprende bastante con el y como persona es una teja.'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULL::TEXT, NULL::SMALLINT, ARRAY[]::TEXT[], '2014-11-15T00:00:00+00:00'::TIMESTAMPTZ, '383f193bd5a6bf8d51c6e431cda2cb915fb58acffed50840480f7cab81ae0934'::TEXT, ARRAY[1017, 1032]::BIGINT[]),
    (311::BIGINT, 'Kirstein es una leyenda.Las clases casi nunca van a ser aburridas, siempre sale con algún chiste malo XD. Deja muchos trabajos, resúmenes todas las semanas (por lo general). Hay que ponerle, no es fácil, pero se aprende demasiado. Y sí, da muchos puntos extra.'::TEXT, 4.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, '90'::TEXT, NULL::SMALLINT, ARRAY[]::TEXT[], '2014-11-15T00:00:00+00:00'::TIMESTAMPTZ, 'a6b0d6bcb8d4b425e60fd06442777df76d100f6a86b6e6a0ca663b7cf05e6f83'::TEXT, ARRAY[1017]::BIGINT[]),
    (311::BIGINT, 'El profe es muy ordenado, es puntual; ademas sube rankings de notas constantemente. Es una teja y un crack. El curso es bastante rudo, pero si uno se compromete Kirstein a uno lo ayuda mucho para pasar con puntos extras; pero al final el que gana es uno porque uno aprende demasiado. Muy recomendado.'::TEXT, 2.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, '100'::TEXT, NULL::SMALLINT, ARRAY[]::TEXT[], '2014-11-15T00:00:00+00:00'::TIMESTAMPTZ, 'c37941bba3d8b697b317bb4fac1f5929658afbc36d8e53e568401b1bf802e301'::TEXT, ARRAY[1032]::BIGINT[]),
    (311::BIGINT, 'Es el mejor Profesor de commpu'::TEXT, 4.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, '100'::TEXT, NULL::SMALLINT, ARRAY[]::TEXT[], '2014-11-15T00:00:00+00:00'::TIMESTAMPTZ, '742bb54abad753830e6f4ed3baf8fd8c304daf119165cb6d5066b1c15431e61d'::TEXT, ARRAY[1017, 1032, 1045]::BIGINT[]),
    (311::BIGINT, 'Uno aprende demasiado, es un crack, demasiado ordenado, siempre bien claro lo que quiere, imposible fallar. Aunque si es mucho brete, pero es solo de entregar todo. Da puntos extras al final por muchas cosas, entre ellas asistencia.'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, '100'::TEXT, NULL::SMALLINT, ARRAY[]::TEXT[], '2014-11-15T00:00:00+00:00'::TIMESTAMPTZ, '6b8760bb75211c56dcacf69865a68f08616275fee095956c40820461be911953'::TEXT, ARRAY[1017]::BIGINT[]),
    (311::BIGINT, 'Ninguno'::TEXT, 2.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, '85'::TEXT, NULL::SMALLINT, ARRAY[]::TEXT[], '2014-11-15T00:00:00+00:00'::TIMESTAMPTZ, '8ff79a5b0fa27e5abe7e8ea61377da7409308bb3df0933fde5e60258b3445623'::TEXT, ARRAY[1032]::BIGINT[]),
    (311::BIGINT, 'excelente profesor, muy rudo pero los puntos extras ayudan mucho'::TEXT, 2.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, '70'::TEXT, NULL::SMALLINT, ARRAY[]::TEXT[], '2014-11-15T00:00:00+00:00'::TIMESTAMPTZ, '8d6a93f0a2234d8c5daf4ca0926cf8a4280c823bd570476fcb001d51c3810cc6'::TEXT, ARRAY[1017]::BIGINT[]),
    (311::BIGINT, 'Es rudo, pero nada mas es de ser ordenado y entregar todo, los puntos extra siempre salvan'::TEXT, 2.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, '85'::TEXT, NULL::SMALLINT, ARRAY[]::TEXT[], '2014-11-15T00:00:00+00:00'::TIMESTAMPTZ, '9800455b1deb3d7ff2cc8458ce9d73577d1a4cccf39ee294e18f126d3d80bc9e'::TEXT, ARRAY[1017]::BIGINT[]),
    (311::BIGINT, 'Ninguno'::TEXT, 6.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, '90'::TEXT, NULL::SMALLINT, ARRAY[]::TEXT[], '2014-11-14T00:00:00+00:00'::TIMESTAMPTZ, '5cffc922737604fe54c8c0c823a87a93d40a43d3828bdab54e803c6c597dc70f'::TEXT, ARRAY[1045, 1017]::BIGINT[]),
    (311::BIGINT, 'humilla a los estudiantes, las tareas que deja son EXCESIVAMENTE largas y complicadas, todas las semanas deja lecturas. Exámenes muy largos, se sufre mucho. Si matriculó con él pulsee todos los puntos extra que pueda'::TEXT, 2.0::NUMERIC(3,1), 3.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, '70'::TEXT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Asistencia obligatoria', 'Clases largas']::TEXT[], '2026-02-09T00:00:00+00:00'::TIMESTAMPTZ, '68e0596422b0e48b197976c1f0170525107ff13e280305abb9f4e1e0899a1094'::TEXT, ARRAY[1017]::BIGINT[]),
    (311::BIGINT, 'Es narcisista, humilla a los estudiantes en clase, pierde demasiado el tiempo de lecciones. Sus lecciones se basan en mejengas, el leyendo su libro y si usted tiene una pregunta, siempre hara que suene estupida. Resumenes de lecturas todas las semenas y tareas PESADISIMAS bisemenal. Haga pts extra'::TEXT, 2.0::NUMERIC(3,1), 4.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, '90'::TEXT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Requiere mucha lectura', 'Deja trabajos largos']::TEXT[], '2025-12-05T00:00:00+00:00'::TIMESTAMPTZ, '099a297ad1e061bbd0dc9573e4ec07f358715fb9235a960ef9bcab323e9e7b94'::TEXT, ARRAY[1017]::BIGINT[]),
    (311::BIGINT, 'El curso se llama Arquitectura pero el da un curso intensivo de ensamblador. Pierde tiempo hablando de mejengas y hay que escucharlo insultando a quienes apoyan a x político. Matricule si quiere experimentar síndrome de Estocolmo.'::TEXT, 2.0::NUMERIC(3,1), 4.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, '80'::TEXT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Requiere mucha lectura', 'Asistencia obligatoria']::TEXT[], '2025-11-28T00:00:00+00:00'::TIMESTAMPTZ, '8778f36aca3dc1a003e8af7355fb0fb49acf3349dacb937e6bbb0cbc1b65a00a'::TEXT, ARRAY[1032]::BIGINT[]),
    (311::BIGINT, 'No matriculé con el, este mae es un hp y tiene la tendencia de humillar a sus alumnos por no saber algo en primer semestre, quiérase de verdad'::TEXT, 2.0::NUMERIC(3,1), 3.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULL::TEXT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Muchas tareas', 'Asistencia obligatoria']::TEXT[], '2025-11-06T00:00:00+00:00'::TIMESTAMPTZ, '984786e634266a99ac1224fda55a522f584a6555a720489962e896e8f740031a'::TEXT, ARRAY[1017]::BIGINT[]),
    (311::BIGINT, 'SI quiere matricular con el o le toco porque no había cupos, sepa que va a sufrir como nunca lo ha hecho. Examenes de 9 horas de 200 preguntas. 5 horas por lecturas a la semana , que acumulan entre 140 en el semestre + siempre un brete bisemanal de mínimo 30 horas, 50 en algunos casos . 50 EX/50 Lec'::TEXT, 2.0::NUMERIC(3,1), 5.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, '70'::TEXT, NULL::SMALLINT, ARRAY['Requiere mucha lectura', 'Deja trabajos largos', 'Exámenes retadores']::TEXT[], '2025-08-29T00:00:00+00:00'::TIMESTAMPTZ, '9a7e369c803e5b582e0143aae0e1b5b6a604f8fab96d038f7ac2be5139b8e6e4'::TEXT, ARRAY[1017]::BIGINT[]),
    (311::BIGINT, 'Simplemente no, por favor quierase un poco y matricule con alguien más que no sea Kirstein o Benavides, es por su propio bien'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, '75'::TEXT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Requiere mucha lectura', 'Exámenes retadores']::TEXT[], '2025-07-22T00:00:00+00:00'::TIMESTAMPTZ, '1af1500c7c5d7e75b64ebbbbeeb28820d05674a93e1ef64eb1e4f5db3cad555e'::TEXT, ARRAY[1017]::BIGINT[]),
    (311::BIGINT, 'Es muy exigente, se hacen entre 130 y 160 resumenes por semestre, las tareas son MUY largas y dificiles, los examenes son los domingos desde las 8 y duran entre 6 y 8 horas, es muy malo explicando pues solo se sienta y empieza a hablar paja, tambien pierde tiempo al inicio con sus "mejengas".'::TEXT, 2.0::NUMERIC(3,1), 4.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, '75'::TEXT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Deja trabajos largos', 'Exámenes retadores']::TEXT[], '2024-05-04T00:00:00+00:00'::TIMESTAMPTZ, 'e90e846a098a8f4b7b0e4780a4f3a04c1572f437b697cabe28eb342089aa3277'::TEXT, ARRAY[1017]::BIGINT[]),
    (311::BIGINT, 'Ninguno'::TEXT, 2.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, '60'::TEXT, NULL::SMALLINT, ARRAY[]::TEXT[], '2024-04-25T00:00:00+00:00'::TIMESTAMPTZ, 'f8322de74ceee34697b8c2b207616a3b774b600c41f321c6e9936813c99b472b'::TEXT, ARRAY[1019]::BIGINT[]),
    (311::BIGINT, 'Después de mi primer año en el tec mi mayor arrepentimiento a sido matricular con el, lleva un ritmo inhumano casi que debería de multiplicar los créditos totales x2, no explica bien solo lee, es mega prepotente por lo tanto no se le puede preguntar nada, y por ultimo examen los domingos.....'::TEXT, 4.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, '55'::TEXT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Muchas tareas', 'Requiere mucha lectura']::TEXT[], '2023-11-23T00:00:00+00:00'::TIMESTAMPTZ, 'a40223c022627bac1d6703846fb57c2c5b2900ad50f2680f3553f545ed85cc27'::TEXT, ARRAY[1032, 1017]::BIGINT[]),
    (311::BIGINT, 'Las tareas son infinitas, deja mínimo 3/4 resumenes semanales de capitulos de 10-100 páginas, los quizzes ni piense que va a poder terminarlos a tiempo en las 2 horas de clase. Los examenes son en domingo y duran 6 horas. No cometa mi error de matricular con él llevando bloque completo'::TEXT, 2.0::NUMERIC(3,1), 4.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULL::TEXT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Requiere mucha lectura', 'Deja trabajos largos']::TEXT[], '2023-03-24T00:00:00+00:00'::TIMESTAMPTZ, 'c0a28196896926747086d545f29c5fb8ad44339c510fab7998aac6ca15539e77'::TEXT, ARRAY[1017]::BIGINT[]),
    (311::BIGINT, 'Es de los profesores más malos de la historia. No sabe lo que es trabajar en otra cosa que no sea dar clases. A los estudiantes que trabajan los tiene entre ojos. No sabe nada del mundo real empresarial.'::TEXT, 6.0::NUMERIC(3,1), 4.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, '70'::TEXT, NULL::SMALLINT, ARRAY['Asistencia obligatoria', 'Deja trabajos largos', 'Exámenes retadores']::TEXT[], '2023-03-18T00:00:00+00:00'::TIMESTAMPTZ, '92ca888c4d5aa84951b1ee38e649abb9f0637416f0b245edbd9229248b328c01'::TEXT, ARRAY[1045]::BIGINT[]),
    (311::BIGINT, 'NO matriculen con este profe, no sean tontos y no comentan ese error es lo peor que pueden hacer es un muyyyyy mal profe, no explica, se la pasa sentado, deja trabajos exageradamente largos, y los examenes son de mas de 180 preguntas los domingos y dura más de 6 horas.'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, '70'::TEXT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Requiere mucha lectura', 'Deja trabajos largos']::TEXT[], '2023-03-02T00:00:00+00:00'::TIMESTAMPTZ, '2af2f2146d3c81996ff0f626290f9a9f3001d6abe44897dad5d077f514926951'::TEXT, ARRAY[1017]::BIGINT[]),
    (311::BIGINT, 'Definitivamente no matriculen con este profesor, fácil podría describirlo como el profe mas anticuado del TEC, el mae piensa que los estudiantes solo están llevando solamente ese curso, deja infinidad de tareas por semana de verdad es de otro mundo, usa métodos de enseñanza muy anticuados.'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, '70'::TEXT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Requiere mucha lectura', 'Exámenes retadores']::TEXT[], '2022-12-16T00:00:00+00:00'::TIMESTAMPTZ, 'b6255fcd0ef7bf8cd56faf97224de423b5c690ed57a5737751046dfb75209fc4'::TEXT, ARRAY[1054]::BIGINT[]),
    (311::BIGINT, 'No vuelvo a matricular con este señor, en mi vida. Aunque tenga que esperarme un semestre para cursar la materia. Él piensa que solo se lleva esa materia. Es demasiado trabajo y muy difícil. DEMASIADO. Porfavor, si valora su salud mental, no matricule con este señor. Se los ruego.'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, '75'::TEXT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Asistencia obligatoria', 'Deja trabajos largos']::TEXT[], '2022-12-04T00:00:00+00:00'::TIMESTAMPTZ, 'cad46b3e88af614184b86c455a48b256176cd3cd5702a160fa30cbf222313d60'::TEXT, ARRAY[1017]::BIGINT[]),
    (311::BIGINT, 'No se haga el daño de matricular con este mae.'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULL::TEXT, NULL::SMALLINT, ARRAY[]::TEXT[], '2022-10-04T00:00:00+00:00'::TIMESTAMPTZ, '1f0f06cdb3fdf6e07ab79e931d16aa3b783f0f0c4ab7932511c94f05ea957cc5'::TEXT, ARRAY[1017]::BIGINT[]),
    (311::BIGINT, 'Mae no metan con este señor, el peor profe del TEC.'::TEXT, 2.0::NUMERIC(3,1), 3.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, '70'::TEXT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Muchas tareas', 'Deja trabajos largos']::TEXT[], '2022-09-10T00:00:00+00:00'::TIMESTAMPTZ, '19ca25252ab0e2397de2a54dd4b6fc8d9085b3e534b21ee961b5a6009aaebd0c'::TEXT, ARRAY[1032]::BIGINT[]),
    (311::BIGINT, 'Es un asco de profe, simplemente no matrícule con él'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULL::TEXT, NULL::SMALLINT, ARRAY['Muchas tareas']::TEXT[], '2022-06-07T00:00:00+00:00'::TIMESTAMPTZ, 'b17d14b31a38a5ff69676fa119fed6252d0eba4d6a55e665a5613ebf9e64b22c'::TEXT, ARRAY[1017]::BIGINT[]),
    (311::BIGINT, 'No sé que es peor, el profesor con su arrogancia y desdén con los estudiantes o los "fans" que dicen que es buenísimo porque "es que matarse y no dormir es aprender". El peor profesor de la vida, ni a mi peor enemigo se lo recomendaría'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULL::TEXT, NULL::SMALLINT, ARRAY[]::TEXT[], '2022-05-30T00:00:00+00:00'::TIMESTAMPTZ, 'e79fbe8c34c4e9ec895cc1ae7896b247607aaf011a168e11b1e80bf9bdb0db8c'::TEXT, ARRAY[1032]::BIGINT[]),
    (311::BIGINT, 'Si esta aquí por que es su única opción matricule en otra sede. Es el peor profesor junto con benavides. Tareas largas y sin sentido. Es machista, se nota ñas preferencias, la materia no tiene nada que ver con los demás cursos de la carrera. En serio esta mejor sin matricular, no lo haga compa'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, '65'::TEXT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Muchas tareas', 'Exámenes retadores']::TEXT[], '2022-04-15T00:00:00+00:00'::TIMESTAMPTZ, '967baef22c42c961b498149f8119b2ec5f0b0f32d62e77097d6e20109c58a4d9'::TEXT, ARRAY[1017, 1032]::BIGINT[]),
    (311::BIGINT, 'Ninguno'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, '70'::TEXT, NULL::SMALLINT, ARRAY[]::TEXT[], '2021-08-12T00:00:00+00:00'::TIMESTAMPTZ, '6a1dd130c3f9ee1c53f5d62e5dcfa6dec9de1f44ba65ac9de7bb75c7a541e479'::TEXT, ARRAY[1045]::BIGINT[]),
    (311::BIGINT, 'Mucha cantidad, poca calidad. El profe lleva como 2 siglos dando los mismos cursos, por lo que conoce muy bien la materia. Tiene preferencia por algunos estudiantes, lo que resulta bastante evidente. La carga es excesiva'::TEXT, 2.0::NUMERIC(3,1), 5.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, '60'::TEXT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Muchas tareas', 'Requiere mucha lectura']::TEXT[], '2021-07-23T00:00:00+00:00'::TIMESTAMPTZ, '679fabfd0710a41853e173f3ad6fb9b492e24bfa3a7407f4535639c551884a65'::TEXT, ARRAY[1017]::BIGINT[]),
    (311::BIGINT, 'El profe es muy simpático y si ve que uno la pulsea le ayuda. Da muchos puntos extras y son muy sencillos. Hasta ir a clases te da puntos. Todas las semanas hay que entregar resúmenes, pero son notas regaladas. Deja tareas largas y exámenes largos. Yo que sentía que me iba a morir termine con 90.'::TEXT, 4.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, '100'::TEXT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Requiere mucha lectura', 'Da crédito extra']::TEXT[], '2021-07-19T00:00:00+00:00'::TIMESTAMPTZ, 'b77aaff9954ee3967989ff52e27cf4edd778db2800fce49aeb5420da62371379'::TEXT, ARRAY[1017]::BIGINT[]),
    (311::BIGINT, 'Me gustaba mucho la materia, sin embargo las tareas eran eternas al igual que los exámenes, por lo que consumía mucho tiempo entonces no se disfruta el curso. Cabe recalcar que sé organizar súper bien mi tiempo e igual habían trabajos que no lograba terminar, para que lo tomen en cuenta :)'::TEXT, 2.0::NUMERIC(3,1), 5.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, '85'::TEXT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Muchas tareas', 'Requiere mucha lectura']::TEXT[], '2021-07-19T00:00:00+00:00'::TIMESTAMPTZ, 'deab6d4379f89f90e57c011c6ae90660b29460244db22a1a063c3266c4c3c82e'::TEXT, ARRAY[1017]::BIGINT[]),
    (311::BIGINT, 'Consume mucho tiempo pero ayuda bastante si uno se lo pide, las clases son solo ejemplos por lo que hay que leer de antemano la materia y hay muchos trabajos con puntos extra'::TEXT, 4.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULL::TEXT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Requiere mucha lectura', 'Da crédito extra']::TEXT[], '2021-07-14T00:00:00+00:00'::TIMESTAMPTZ, '10bf93252806c94837e34fbc6757926d26f13d86c7b153af7ffd2a2d89b57f5a'::TEXT, ARRAY[1032]::BIGINT[]),
    (311::BIGINT, 'No lo recomiendo. Consume mucho tiempo para al final aprender muy poco. No explica claro. Las clases son casi solo el programando.'::TEXT, 2.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, '60'::TEXT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Requiere mucha lectura', 'Deja trabajos largos']::TEXT[], '2021-07-11T00:00:00+00:00'::TIMESTAMPTZ, '4dbb840f71f66ffdaebb916cebd1223dd9348fa68c88526cb2719afd4c499564'::TEXT, ARRAY[1032]::BIGINT[]),
    (311::BIGINT, 'En virtual deja la misma cantidad de tareas que presencial, que son bastantes. Pero al ser tantas no ocupa nota perfecta para pasar, con solo hacerlas está bien. Siempre aclara dudas, los exámenes son largos y difíciles, da muchas ayudas extras para que todos los que hagan sus tareas pasen'::TEXT, 4.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, '80'::TEXT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Requiere mucha lectura', 'Da crédito extra']::TEXT[], '2020-08-26T00:00:00+00:00'::TIMESTAMPTZ, '72c99a65d2fca43b84250bed5c9f9176f334f07f3278e7b60ce46adb48b5618e'::TEXT, ARRAY[1032]::BIGINT[]),
    (311::BIGINT, 'el mae en virtual no explica de manera sincrónica, pero envía su libro y es leer una explicación en clase. Es muy cansado por todos los trabajos pero si le pone desde el principio va a pasarla bien. Da muchos puntos extra, es algo pesado en general.'::TEXT, 4.0::NUMERIC(3,1), 5.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, '95'::TEXT, NULL::SMALLINT, ARRAY['Requiere mucha lectura', 'Da crédito extra', 'Deja trabajos largos']::TEXT[], '2020-08-24T00:00:00+00:00'::TIMESTAMPTZ, '4e7d54b80fddd807b95231250662c9813eee42a2d2030b25d5c3194b68336679'::TEXT, ARRAY[1017]::BIGINT[]),
    (311::BIGINT, 'Muchas tareas semanales, en la primera mitad del curso debe leerse 3 capítulos de distintos libros y resumir los cada semana, luego sube a 5. Eso sumado a las tareas se hace mucho trabajo. Usa tecnologías muy antiguas, incluso en una tarea hay que instalarse un programa que necesita Windows xp.'::TEXT, 2.0::NUMERIC(3,1), 4.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, '75'::TEXT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Requiere mucha lectura', 'Deja trabajos largos']::TEXT[], '2020-08-16T00:00:00+00:00'::TIMESTAMPTZ, '2f61afc42398599a2f4833bd4a69cd184c9841a694a7b7cd838e52299a9358e5'::TEXT, ARRAY[1017]::BIGINT[]),
    (311::BIGINT, 'Deja demasiadas tareas, no explica bien y hace exámenes muy difíciles.'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, '80'::TEXT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Requiere mucha lectura', 'Exámenes retadores']::TEXT[], '2020-08-06T00:00:00+00:00'::TIMESTAMPTZ, '2203f97dcc287630f47b36edf96a42267d19e4dc4448a60a16c3d967e3b14a52'::TEXT, ARRAY[1017]::BIGINT[]),
    (311::BIGINT, 'Ninguno'::TEXT, 4.0::NUMERIC(3,1), 5.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, '70'::TEXT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Requiere mucha lectura', 'Deja trabajos largos']::TEXT[], '2020-02-14T00:00:00+00:00'::TIMESTAMPTZ, '93723010be4f97739e294a9b836f4175e304b5afacc1e927d12318bcb963d1d6'::TEXT, ARRAY[1032]::BIGINT[]),
    (311::BIGINT, 'Deja tareas cortas y largas todas las semanas, con que las haga pasa el curso, da muchos puntos extra, los examenes son muy largos y medio dificiles pero bien bien los pasa con 50, todas las tareas se hacen individuales. Es muy pura vida y se aprende bastante, responde dudas'::TEXT, 4.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, '75'::TEXT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Requiere mucha lectura', 'Exámenes retadores']::TEXT[], '2020-02-04T00:00:00+00:00'::TIMESTAMPTZ, '22a19fa35ccfbfde7bc7d59f8fec223969b0575e1daf61f010bd4079d5700500'::TEXT, ARRAY[1017]::BIGINT[]),
    (311::BIGINT, 'Pasa hablando de su familia y mejengas, entonces intenta dar la materia en los últimos 20 minutos de clase, por lo que hay que pasar reponiendo clase y no explica bien. Exámenes larguísimos y DEMASIADOS trabajos. Por algo es que ofrece tantas oportunidades de puntos extra.'::TEXT, 2.0::NUMERIC(3,1), 3.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, '75'::TEXT, NULL::SMALLINT, ARRAY[]::TEXT[], '2020-02-03T00:00:00+00:00'::TIMESTAMPTZ, '0e87cf7dd3d1877fe2690bb6e9312a240953bb0c188baa6c609ddb11e1637aa0'::TEXT, ARRAY[1017]::BIGINT[]),
    (311::BIGINT, 'No lo haga compa'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, '55'::TEXT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Clases largas', 'Muchos exámenes']::TEXT[], '2019-08-14T00:00:00+00:00'::TIMESTAMPTZ, 'f92f89c0d251acc90d2553dc5fefc9f13c51e470ab889794332cb43dc045b28f'::TEXT, ARRAY[1017]::BIGINT[]),
    (311::BIGINT, 'Un curso interesante. Lo considero buen profe para este curso'::TEXT, 6.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, '100'::TEXT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Requiere mucha lectura', 'Asistencia obligatoria']::TEXT[], '2019-06-18T00:00:00+00:00'::TIMESTAMPTZ, '2a81e78c4a996721e24d6e24593843b6fa5ce6253d8e237b3f977530eec4e6e7'::TEXT, ARRAY[1054]::BIGINT[]),
    (311::BIGINT, 'El vive en la edad de piedra, este profe tiene de poca a 0 experiencia laboral, si quieren saber todo lo que no es la carrera, él da esa materia, si tiene posibilidad con otro profe mejor o adelante otro curso pero no desperdicie su tiempo'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, '70'::TEXT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Muchas tareas', 'Deja trabajos largos']::TEXT[], '2019-04-28T00:00:00+00:00'::TIMESTAMPTZ, '3256514e7e3d811438f5194416b2b6f1cb2546b1aeebaaccc9423bf86146253e'::TEXT, ARRAY[1017]::BIGINT[]),
    (311::BIGINT, 'Ninguno'::TEXT, 2.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULL::TEXT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Muchas tareas', 'Requiere mucha lectura']::TEXT[], '2019-02-16T00:00:00+00:00'::TIMESTAMPTZ, '96558ea2227dc5b87f7de47e1d66e2bec8b30dc92855085a46dfa53b930ca740'::TEXT, ARRAY[1017]::BIGINT[]),
    (311::BIGINT, 'Si puede meter con otro profe hagalo, cada clase es una agonia y son obligatorias por que sin la nota extra de la asistencia casi nadie pasa por lo que tiene que escuchar 10 minutos de materia y 2h de sus historias , la clase podria durar una hora si el profe diera la materia y no hablara de mejenga'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, '70'::TEXT, NULL::SMALLINT, ARRAY['Da crédito extra', 'Deja trabajos largos']::TEXT[], '2018-12-05T00:00:00+00:00'::TIMESTAMPTZ, '5df7abd2aa710f853c609f91b71b0f3df866355e40cbb36bb273fcecbe4f03ab'::TEXT, ARRAY[1017]::BIGINT[]),
    (311::BIGINT, 'Ni tan bueno, ni tan malo. Realmente está un poco sobrevalorado, no le gusta ayudar mucho en clase y fuera de clases es imposible verlo, solo ayuda por correo o por el foro. Se desperdicia mucho algunas clases (muchas) y otras las aprovecha demasiado. Pasarle no es complicado, solo hacer resúmenes.'::TEXT, 4.0::NUMERIC(3,1), 4.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, '85'::TEXT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Requiere mucha lectura', 'Da crédito extra']::TEXT[], '2018-11-27T00:00:00+00:00'::TIMESTAMPTZ, 'f902ab67441c071064fcc16a043f049af0e64eef6ded98b8ee229a24010f4d7a'::TEXT, ARRAY[1045]::BIGINT[]),
    (311::BIGINT, 'Si preguntas algo te responde de manera grosera, no explica muy claro en clases, pero al fin y al cabo se aprende bastante, deja muchas tareas y resúmenes, y se pueden ganar bastantes puntos extras. Sí usted puede soportar la presión de los demás cursos y este que vale como 6 créditos no lo dude.'::TEXT, 4.0::NUMERIC(3,1), 5.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, '70'::TEXT, NULL::SMALLINT, ARRAY[]::TEXT[], '2018-11-12T00:00:00+00:00'::TIMESTAMPTZ, '30c9ce9413d5ef026d9268e1a8262c3902577dfd6753be911342fd31dd075465'::TEXT, ARRAY[1017]::BIGINT[]),
    (311::BIGINT, 'Nadie va a negar que el profe sabe mucho, pero no tiene la dedicación para enseñar. Deja una exageración de trabajos para una semana y los exámenes son domingos de 6 a 7 horas. La única ventaja es que da muchos puntos extras por cualquier cosilla, pero no explica nada bien y pierde mucho tiempo.'::TEXT, 4.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, '70'::TEXT, NULL::SMALLINT, ARRAY[]::TEXT[], '2018-11-10T00:00:00+00:00'::TIMESTAMPTZ, 'e646174995f3afb0807d183edac4400047f12cbbd8e8b7ea966b83618c732ad9'::TEXT, ARRAY[1017]::BIGINT[]),
    (311::BIGINT, 'Ninguno'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, '65'::TEXT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Muchas tareas', 'Asistencia obligatoria']::TEXT[], '2018-05-30T00:00:00+00:00'::TIMESTAMPTZ, 'e912c7c6d4f128f54627a71a1b67d90837fb23b684709f16b6b6453efca86499'::TEXT, ARRAY[1017]::BIGINT[]),
    (311::BIGINT, 'Ninguno'::TEXT, 2.0::NUMERIC(3,1), 3.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULL::TEXT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Muchas tareas', 'Requiere mucha lectura']::TEXT[], '2017-11-22T00:00:00+00:00'::TIMESTAMPTZ, '9c6b38a37554109d3431561baf7828bfbbb2ef686099fd77e1df2ffb563d4113'::TEXT, ARRAY[1017]::BIGINT[]),
    (311::BIGINT, '+ Todas las semanas vas a estar haciendo resúmenes(como todos los cursos que da) + El compilador lo vas a construir a pie sin herramientas/frameworks + Si no tienes claro que hacer en una etapa del proyecto, estás jodido porque kirstein no tiene consulta personal + Aprenderas los inútiles automatas'::TEXT, 2.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, '85'::TEXT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Requiere mucha lectura', 'Da crédito extra']::TEXT[], '2017-07-21T00:00:00+00:00'::TIMESTAMPTZ, 'c1c3c7430adf10ac3ddcae6db002aae417d6682dbbfb735f8d2dce130ffb2792'::TEXT, ARRAY[1054]::BIGINT[]),
    (311::BIGINT, 'Hay que estudiar mucho para pasar el curso, perp con él se aprende demasiado. Es muy estricto con la asistencia y el control de plagio.'::TEXT, 2.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULL::TEXT, NULL::SMALLINT, ARRAY['Muy cómico', 'Muchas tareas', 'Requiere mucha lectura']::TEXT[], '2017-06-30T00:00:00+00:00'::TIMESTAMPTZ, '63d8e22f3b7478c0c7732a8fc79c28952bf79370b902015e0fc3f7da79cca3a0'::TEXT, ARRAY[1017]::BIGINT[]),
    (311::BIGINT, 'El que mejor lo prepara a uno para la dificultad que vendrá a lo largo de la carrera. Siempre hay trabajos que hacer, es bien difícil mantenerse al día. Al final uno siente como que todo el esfuerzo valió la pena y que aprendió en un semestre más que en toda su vida. Al final regala como 10pts extra'::TEXT, 2.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, '75'::TEXT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Muchas tareas', 'Requiere mucha lectura']::TEXT[], '2017-06-27T00:00:00+00:00'::TIMESTAMPTZ, '0e49bebae3e13ddbf839a62c42bb77f4b983401b3ab30b940d365b4ac72f04e7'::TEXT, ARRAY[1017]::BIGINT[]),
    (311::BIGINT, 'El sabe mucho, los exámenes son estúpidamente largos, las clases entretenidas pero prepárese para pasar estresado y bajo presión todo el semestre'::TEXT, 2.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, '70'::TEXT, NULL::SMALLINT, ARRAY['Requiere mucha lectura', 'Deja trabajos largos', 'Exámenes retadores']::TEXT[], '2017-01-19T00:00:00+00:00'::TIMESTAMPTZ, 'f11d7852c375dd2f4733bebbc24e629ad9a611311da42fa7136e7ea6bc9c8e76'::TEXT, ARRAY[1017]::BIGINT[]),
    (311::BIGINT, 'Es buena gente pero no explica muy bien, deja como 200 tareas por semestre, repone clases, habla paja asi que se distrae y los examenes son como de ocho horas los domingos(no estoy vacilando). Eso si, ayuda bastante y da putos extra'::TEXT, 4.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, '70'::TEXT, NULL::SMALLINT, ARRAY[]::TEXT[], '2017-01-14T00:00:00+00:00'::TIMESTAMPTZ, '04929c8f1df6a26fd9b2b3c811fb9fd3dbe217e943ff294083ca2b14454ca478'::TEXT, ARRAY[1017]::BIGINT[]),
    (311::BIGINT, 'Excelente porfesor. Deja tandas de hasta 5 lecturas semanales de las que hay que hacer resumenes. Uno aprende muchisimo de todo porque el conocimiento que el tiene no siempre esta en Google sino hque hay que buscarlo en muchos libros'::TEXT, 4.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, '70'::TEXT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Requiere mucha lectura', 'Da crédito extra']::TEXT[], '2016-05-28T00:00:00+00:00'::TIMESTAMPTZ, 'fead4dbee6e5482db15792f0293f97563042d78ea03c34df054792e39c3ef45a'::TEXT, ARRAY[1017]::BIGINT[]),
    (311::BIGINT, 'Ninguno'::TEXT, 2.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, '75'::TEXT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Da crédito extra', 'Exámenes retadores']::TEXT[], '2016-02-26T00:00:00+00:00'::TIMESTAMPTZ, 'd3bdf87857bd1915ce70069a1dd68e90b6d16d431c7105a035fe4ed7fb77d939'::TEXT, ARRAY[1017]::BIGINT[]),
    (311::BIGINT, 'Si es primer ingreso, mejor no matricule con él. Kirstein exige mucho y le gusta que usted se asuste.No es fácil pedirle ayuda, sus clases no son claras, se basa en materia viejisima en videobeam, muchas tareas largas, exámenes de 6 horas los fines de semana. Tenés que ponerle mucho desde el inicio.'::TEXT, 2.0::NUMERIC(3,1), 4.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, '75'::TEXT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Deja trabajos largos', 'Exámenes retadores']::TEXT[], '2016-02-05T00:00:00+00:00'::TIMESTAMPTZ, '25d0159c7ca322aff95735584a1ce63e45fa92b9ae3d586192e3dfc24357eb4f'::TEXT, ARRAY[1017]::BIGINT[]),
    (311::BIGINT, 'Cualquier curso con él se hace muy pesado, muchos resúmenes y proyectos. Las lecturas son bastante profundas y complicadas. Pero si cumple con todo y aún le faltan puntos el ayuda. Tienes que vivir en el foro de IC. Y los exámenes que él hace deberían ser ilegales. Matricule si no hay de otra.'::TEXT, 2.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, '70'::TEXT, NULL::SMALLINT, ARRAY[]::TEXT[], '2016-02-04T00:00:00+00:00'::TIMESTAMPTZ, '1b42daceeae727a1a067d19085f208a26c2d7c2116fdf700af7af11ffb7082cb'::TEXT, ARRAY[1017]::BIGINT[]),
    (311::BIGINT, 'Es muy divertido'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, '100'::TEXT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-06-18T00:00:00+00:00'::TIMESTAMPTZ, 'ac2fcc3ea3bb9517bc41c843a67c192290d298ccaa6a6de01941041f5b7d09cd'::TEXT, ARRAY[1045]::BIGINT[]),
    (311::BIGINT, 'Si llevas Kirstein + 3 o 4 cursos, no te prometo el cielo.'::TEXT, 4.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULL::TEXT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-06-10T00:00:00+00:00'::TIMESTAMPTZ, '8d2fdb40d845734c517080eac5e1899265c37e6f0db78ad5480a7a19ffcef614'::TEXT, ARRAY[1017]::BIGINT[]),
    (311::BIGINT, 'No se siente ambiente de respeto en la clase. En el curso de Arqui no daba los temas claros, asumía muchas cosas que no todos sabíamos'::TEXT, 2.0::NUMERIC(3,1), 4.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, '10'::TEXT, NULL::SMALLINT, ARRAY[]::TEXT[], '2014-12-01T00:00:00+00:00'::TIMESTAMPTZ, '695bf913af44d201dea8f555077d8a5e03a3d82b8483982a49e106e72bc4fc13'::TEXT, ARRAY[1032]::BIGINT[]),
    (311::BIGINT, 'Uno aprende demaciado con él'::TEXT, 4.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, '95'::TEXT, NULL::SMALLINT, ARRAY[]::TEXT[], '2014-11-21T00:00:00+00:00'::TIMESTAMPTZ, '1e3485d817becc58c6f297afc81ccd1d2196ed7c81edf8cbeddcd600f07f8321'::TEXT, ARRAY[1032]::BIGINT[]),
    (311::BIGINT, 'Si usted no es vago, pasa'::TEXT, 2.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULL::TEXT, NULL::SMALLINT, ARRAY[]::TEXT[], '2014-11-18T00:00:00+00:00'::TIMESTAMPTZ, '8e88dc2c12f953699e8d7d21b7c4b9d61ed977b4136a8e0f6bcd38762b096468'::TEXT, ARRAY[1017]::BIGINT[]),
    (311::BIGINT, 'Excelente profe, el curso con el es muy matado pero se aprende en demasía de un monton de temas. Si le pone bastante, seguramente pasa.'::TEXT, 2.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, '100'::TEXT, NULL::SMALLINT, ARRAY[]::TEXT[], '2014-11-18T00:00:00+00:00'::TIMESTAMPTZ, 'b4f8f86bdcae4b6817e67792396879207a6162391b68d242a94eba1799e86442'::TEXT, ARRAY[1017, 1032]::BIGINT[]),
    (311::BIGINT, 'Se aprende demasiado en el curso'::TEXT, 4.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, '80'::TEXT, NULL::SMALLINT, ARRAY[]::TEXT[], '2014-11-17T00:00:00+00:00'::TIMESTAMPTZ, '62a1686ab8d447fe8e535156c217154412c5858461369c09aa869cdc6a1d49b4'::TEXT, ARRAY[1032]::BIGINT[]),
    (311::BIGINT, 'Ninguno'::TEXT, 2.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULL::TEXT, NULL::SMALLINT, ARRAY[]::TEXT[], '2014-11-17T00:00:00+00:00'::TIMESTAMPTZ, 'c2fbc7020a89240ae819716e915ce8af4960297150c8288fa1d773683e467f8c'::TEXT, ARRAY[1017]::BIGINT[])
), inserted_review AS (
  INSERT INTO public.professor_review (
    professor_id, comment, ease_score, quality_score, clarity_score, fairness_score,
    attendance_required, grade_received, engagement_level, tags, status, reviewed_at, created_at, updated_at, import_key
  )
  SELECT 
    professor_id, comment, ease_score, quality_score, clarity_score, fairness_score,
    attendance_required, grade_received, engagement_level, tags, 'approved'::public.professor_review_status, now(), created_at, created_at, import_key
  FROM review_input ri
  WHERE NOT EXISTS (
    SELECT 1 FROM public.professor_review pr WHERE pr.import_key = ri.import_key
  )
  RETURNING id, import_key
), target_review AS (
  SELECT id, import_key FROM inserted_review
  UNION ALL
  SELECT pr.id, pr.import_key
  FROM public.professor_review pr
  JOIN review_input ri ON ri.import_key = pr.import_key
)
INSERT INTO public.professor_review_course (review_id, course_id)
SELECT tr.id, course_id
FROM target_review tr
JOIN review_input ri ON ri.import_key = tr.import_key
CROSS JOIN LATERAL unnest(ri.course_ids) AS course_id
ON CONFLICT DO NOTHING;

COMMIT;
